-- ===== work-files-local.sql =====
-- LOCAL PRO ONLY. Immutable private files, interrupted-upload recovery and explicit sharing.
-- New bucket only; no delivery bucket/table writes, notifications, messages or outbox.
begin;
create table if not exists public.pro_work_files(
 id uuid primary key,owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,
 source_name text not null check(length(source_name) between 1 and 160 and source_name !~ '[[:cntrl:]/]' and position(chr(92) in source_name)=0),
 name text not null check(length(name) between 1 and 160 and name !~ '[[:cntrl:]/]' and position(chr(92) in name)=0),
 mime_type text not null check(mime_type in('image/jpeg','application/pdf')),
 raw_sha256 text not null check(raw_sha256~'^[a-f0-9]{64}$'),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 size_bytes integer not null check(size_bytes>0 and size_bytes<=20971520),object_path text not null unique,
 revision integer not null default 1 check(revision in(1,2)),ready boolean not null default false,created_at timestamptz not null default now(),
 -- Captured recipient identity is not a blocking profile FK: deleting the
 -- customer account must not delete or block the provider's immutable file.
 published_at timestamptz,client_user_id uuid,recipient_name text,service text,
 unique(owner_id,work_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 check(mime_type<>'image/jpeg' or size_bytes<=20971520),
 check(object_path=owner_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end),
 check(right(name,4)=case when mime_type='application/pdf' then '.pdf' else '.jpg' end),
 check((revision=1 and published_at is null and client_user_id is null and recipient_name is null and service is null)
 or (revision=2 and ready and published_at is not null and client_user_id is not null and recipient_name is not null and service is not null and length(recipient_name) between 1 and 160 and length(service) between 1 and 160))
);
create index if not exists pro_work_files_owner_page on public.pro_work_files(owner_id,work_id,created_at desc,id desc);
create index if not exists pro_work_files_shared_page on public.pro_work_files(client_user_id,owner_id,work_id,created_at desc,id desc) where ready and revision=2;
create table if not exists public.pro_work_file_upload_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,file_id uuid not null references public.pro_work_files(id) on delete cascade,
 input jsonb not null,result jsonb,at timestamptz not null default now(),primary key(actor_id,file_id)
);
create table if not exists public.pro_work_file_publish_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id)
);
create or replace function public.pro_work_file_json(p_file public.pro_work_files) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_file.id,'workId',p_file.work_id,'name',p_file.name,'mimeType',p_file.mime_type,'sizeBytes',p_file.size_bytes,
 'sha256',p_file.sha256,'revision',p_file.revision,'ready',p_file.ready,'createdAt',p_file.created_at,'publishedAt',p_file.published_at);
$$;
create or replace function public.pro_work_files_read(p_actor uuid,p_work text,p_after uuid default null,p_file uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare file public.pro_work_files;cursor_time timestamptz;cursor_id uuid;items jsonb;recipient uuid;recipient_name text;can_share boolean:=false;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or p_after is not null and p_file is not null then raise exception 'Invalid file query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then return null;end if;
 select r.client_user_id,r.client_name into recipient,recipient_name from public.pro_appointment_requests r
 join public.pro_work w on w.user_id=r.owner_id and w.id=r.work_id join public.profiles c on c.id=r.client_user_id
 where r.owner_id=p_actor and r.work_id=p_work and r.status in('confirmed','completed') and not coalesce(w.cancelled,false) and not coalesce(c.is_disabled,false);
 can_share:=found;
 if p_file is not null then
  select * into file from public.pro_work_files where owner_id=p_actor and work_id=p_work and id=p_file;
  if not found then return null;end if;
  return jsonb_build_object('file',public.pro_work_file_json(file),'canShare',can_share,'recipientId',recipient,'recipientName',recipient_name);
 end if;
 if p_after is not null then
  select created_at into cursor_time from public.pro_work_files where owner_id=p_actor and work_id=p_work and id=p_after;
  if not found then raise exception 'Invalid file cursor' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(public.pro_work_file_json(f::public.pro_work_files) order by f.created_at desc,f.id desc),'[]'::jsonb) into items from (
  select * from public.pro_work_files where owner_id=p_actor and work_id=p_work and (p_after is null or (created_at,id)<(cursor_time,p_after)) order by created_at desc,id desc limit 21
 ) f;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id,'canShare',can_share,'recipientId',recipient,'recipientName',recipient_name);
end $$;
create or replace function public.pro_work_files_client_read(p_actor uuid,p_request uuid,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare owner uuid;wid text;cursor_time timestamptz;cursor_id uuid;items jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select owner_id,work_id into owner,wid from public.pro_appointment_requests where id=p_request and client_user_id=p_actor and work_id is not null;
 if not found then return null;end if;
 if p_after is not null then
  select created_at into cursor_time from public.pro_work_files where id=p_after and owner_id=owner and work_id=wid and ready and revision=2 and client_user_id=p_actor;
  if not found then raise exception 'Invalid shared file cursor' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(x.content order by x.created_at desc,x.id desc),'[]'::jsonb) into items from (
  select f.created_at,f.id,jsonb_build_object('id',f.id,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256,'publishedAt',f.published_at,'service',f.service) as content
  from public.pro_work_files f where f.owner_id=owner and f.work_id=wid and f.ready and f.revision=2 and f.client_user_id=p_actor
  and (p_after is null or (f.created_at,f.id)<(cursor_time,p_after)) order by f.created_at desc,f.id desc limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_work_file_download(p_actor uuid,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare file public.pro_work_files;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into file from public.pro_work_files where id=p_file and ready;
 if not found then return null;end if;
 if file.owner_id=p_actor then
  if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 elsif file.revision<>2 or file.client_user_id is distinct from p_actor or not exists(select 1 from public.pro_appointment_requests where owner_id=file.owner_id and work_id=file.work_id and client_user_id=p_actor) then return null;
 end if;
 return jsonb_build_object('objectPath',file.object_path,'name',file.name,'mimeType',file.mime_type,'sizeBytes',file.size_bytes,'sha256',file.sha256);
end $$;
create or replace function public.pro_work_file_reserve(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare fid uuid;wid text;keys text[];receipt public.pro_work_file_upload_actions;file public.pro_work_files;mime text;bytes integer;path text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid file' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys<>array['fileId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName','workId']
 or jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string'
 or jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sourceName') is distinct from 'string'
 or jsonb_typeof(p_input->'mimeType') is distinct from 'string' or jsonb_typeof(p_input->'rawSha256') is distinct from 'string' or jsonb_typeof(p_input->'sha256') is distinct from 'string'
 or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' then raise exception 'Invalid file fields' using errcode='22023';end if;
 fid:=(p_input->>'fileId')::uuid;wid:=p_input->>'workId';mime:=p_input->>'mimeType';
 if length(wid) not between 1 and 160 or mime not in('image/jpeg','application/pdf') or not coalesce((p_input->>'rawSha256')~'^[a-f0-9]{64}$',false) or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false)
 or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false) then raise exception 'Invalid file metadata' using errcode='22023';end if;
 bytes:=(p_input->>'sizeBytes')::integer;if bytes<1 or bytes>20971520 or mime='image/jpeg' and bytes>20971520 then raise exception 'File too large' using errcode='22023';end if;
 if not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-file-upload:'||p_actor::text||':'||fid::text,0));
 select * into receipt from public.pro_work_file_upload_actions where actor_id=p_actor and file_id=fid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Upload identity reused with different bytes or metadata' using errcode='22023';end if;
  select * into file from public.pro_work_files where id=fid and owner_id=p_actor and work_id=wid;
  return jsonb_build_object('file',coalesce(receipt.result->'file',public.pro_work_file_json(file)),'objectPath',file.object_path);
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-files:'||p_actor::text||':'||wid,0));
 perform 1 from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if (select count(*) from public.pro_work_files where owner_id=p_actor and work_id=wid)>=100 then raise exception 'File limit reached' using errcode='54000';end if;
 path:=p_actor::text||'/'||fid::text||case when mime='application/pdf' then '.pdf' else '.jpg' end;
 insert into public.pro_work_files(id,owner_id,work_id,source_name,name,mime_type,raw_sha256,sha256,size_bytes,object_path)
 values(fid,p_actor,wid,p_input->>'sourceName',p_input->>'name',mime,p_input->>'rawSha256',p_input->>'sha256',bytes,path) returning * into file;
 insert into public.pro_work_file_upload_actions(actor_id,file_id,input) values(p_actor,fid,p_input);
 return jsonb_build_object('file',public.pro_work_file_json(file),'objectPath',path);
end $$;
create or replace function public.pro_work_file_ready(p_actor uuid,p_file uuid,p_sha256 text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare receipt public.pro_work_file_upload_actions;file public.pro_work_files;ack_result jsonb;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-file-upload:'||p_actor::text||':'||p_file::text,0));
 select * into receipt from public.pro_work_file_upload_actions where actor_id=p_actor and file_id=p_file for update;
 if not found then raise exception 'Upload not reserved' using errcode='42501';end if;
 select * into file from public.pro_work_files where id=p_file and owner_id=p_actor for update;
 if not found or file.sha256 is distinct from p_sha256 then raise exception 'Upload content changed' using errcode='22023';end if;
 if receipt.result is not null then return receipt.result;end if;
 if file.revision<>1 then raise exception 'Upload state changed' using errcode='40001';end if;
 update public.pro_work_files set ready=true where id=p_file returning * into file;
 ack_result:=jsonb_build_object('file',public.pro_work_file_json(file));
 update public.pro_work_file_upload_actions set result=ack_result where actor_id=p_actor and file_id=p_file;
 return ack_result;
end $$;
create or replace function public.pro_work_file_publish(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare fid uuid;wid text;aid uuid;recipient uuid;keys text[];receipt public.pro_work_file_publish_actions;file public.pro_work_files;w public.pro_work;r public.pro_appointment_requests;result jsonb;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid publication' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys<>array['action','actionId','fileId','recipientId','revision','workId'] or p_input->>'action' is distinct from 'publish'
 or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'fileId') is distinct from 'string' or jsonb_typeof(p_input->'recipientId') is distinct from 'string'
 or jsonb_typeof(p_input->'workId') is distinct from 'string' or p_input->'revision' is distinct from '1'::jsonb then raise exception 'Invalid publication fields' using errcode='22023';end if;
 fid:=(p_input->>'fileId')::uuid;wid:=p_input->>'workId';aid:=(p_input->>'actionId')::uuid;recipient:=(p_input->>'recipientId')::uuid;
 if length(wid) not between 1 and 160 or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-file-publish:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_work_file_publish_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Publication identity changed' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-work-files:'||p_actor::text||':'||wid,0));
 -- Match appointment actions: linked request before work, never the reverse.
 select * into r from public.pro_appointment_requests where owner_id=p_actor and work_id=wid for share;
 if not found then raise exception 'No linked customer' using errcode='42501';end if;
 select * into w from public.pro_work where user_id=p_actor and id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 select * into file from public.pro_work_files where id=fid and owner_id=p_actor and work_id=wid for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if file.revision<>1 then raise exception 'File changed' using errcode='40001';end if;
 if not file.ready then raise exception 'Upload is not ready' using errcode='22023';end if;
 if r.client_user_id<>recipient then raise exception 'Recipient changed' using errcode='40001';end if;
 if coalesce(w.cancelled,false) or r.status not in('confirmed','completed') or not exists(select 1 from public.profiles where id=recipient and not coalesce(is_disabled,false)) then raise exception 'Customer unavailable' using errcode='42501';end if;
 update public.pro_work_files set revision=2,published_at=now(),client_user_id=r.client_user_id,recipient_name=r.client_name,service=w.service where id=fid returning * into file;
 result:=jsonb_build_object('file',public.pro_work_file_json(file));
 insert into public.pro_work_file_publish_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);return result;
end $$;
create or replace function public.pro_work_file_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (to_jsonb(new)-array['ready','revision','published_at','client_user_id','recipient_name','service']) is distinct from (to_jsonb(old)-array['ready','revision','published_at','client_user_id','recipient_name','service']) then raise exception 'File content metadata is immutable' using errcode='23514';end if;
 if old.revision=2 and new is distinct from old or old.ready and not new.ready then raise exception 'Shared file is immutable' using errcode='23514';end if;
 if new.revision=old.revision then
  if (to_jsonb(new)-'ready') is distinct from (to_jsonb(old)-'ready') then raise exception 'Invalid upload transition' using errcode='23514';end if;
 elsif old.revision<>1 or new.revision<>2 or not old.ready or not new.ready then raise exception 'Invalid file sharing transition' using errcode='23514';end if;
 return new;
end $$;
create or replace function public.pro_work_file_upload_receipt_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if old.result is not null or new.result is null or (to_jsonb(new)-'result') is distinct from (to_jsonb(old)-'result') then raise exception 'Upload receipt is immutable after confirmation' using errcode='23514';end if;return new;
end $$;
create or replace function public.pro_work_file_publish_receipt_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Publication receipt is immutable' using errcode='23514';end $$;
drop trigger if exists pro_work_file_immutable on public.pro_work_files;
create trigger pro_work_file_immutable before update on public.pro_work_files for each row execute function public.pro_work_file_immutable();
drop trigger if exists pro_work_file_upload_receipt_immutable on public.pro_work_file_upload_actions;
create trigger pro_work_file_upload_receipt_immutable before update on public.pro_work_file_upload_actions for each row execute function public.pro_work_file_upload_receipt_immutable();
drop trigger if exists pro_work_file_publish_receipt_immutable on public.pro_work_file_publish_actions;
create trigger pro_work_file_publish_receipt_immutable before update on public.pro_work_file_publish_actions for each row execute function public.pro_work_file_publish_receipt_immutable();
alter table public.pro_work_files enable row level security;alter table public.pro_work_file_upload_actions enable row level security;alter table public.pro_work_file_publish_actions enable row level security;
revoke all on public.pro_work_files,public.pro_work_file_upload_actions,public.pro_work_file_publish_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_files,public.pro_work_file_upload_actions,public.pro_work_file_publish_actions to service_role;
revoke all on function public.pro_work_file_json(public.pro_work_files),public.pro_work_files_read(uuid,text,uuid,uuid),public.pro_work_files_client_read(uuid,uuid,uuid),public.pro_work_file_download(uuid,uuid),public.pro_work_file_reserve(uuid,jsonb),public.pro_work_file_ready(uuid,uuid,text),public.pro_work_file_publish(uuid,jsonb),public.pro_work_file_immutable(),public.pro_work_file_upload_receipt_immutable(),public.pro_work_file_publish_receipt_immutable() from public,anon,authenticated;
grant execute on function public.pro_work_file_json(public.pro_work_files),public.pro_work_files_read(uuid,text,uuid,uuid),public.pro_work_files_client_read(uuid,uuid,uuid),public.pro_work_file_download(uuid,uuid),public.pro_work_file_reserve(uuid,jsonb),public.pro_work_file_ready(uuid,uuid,text),public.pro_work_file_publish(uuid,jsonb) to service_role;
do $$begin
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-work-files','pro-work-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;
  if not exists(select 1 from storage.buckets where id='pro-work-files' and not public and file_size_limit=20971520 and allowed_mime_types @> array['image/jpeg','application/pdf'] /* Ronda F2-D: file-formats-library-local.sql widens the list */) then raise exception 'Work files bucket configuration must match the private contract';end if;
 end if;
 if to_regclass('storage.objects') is not null then
  execute 'drop policy if exists pro_work_files_no_direct on storage.objects';
  execute 'create policy pro_work_files_no_direct on storage.objects as restrictive for all to anon,authenticated using (bucket_id <> ''pro-work-files'') with check (bucket_id <> ''pro-work-files'')';
 end if;
end $$;
commit;

-- ===== team-local.sql =====
-- LOCAL PRO ONLY. Owner-scoped team access, manual invitation codes and real-actor audit.
-- Codes are SHA256 hashes supplied by the server; no raw code, email delivery or impersonation.
begin;
create table if not exists public.pro_team_invites(
 id uuid primary key,owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,
 recipient_email text not null check(length(recipient_email) between 3 and 254 and recipient_email=lower(btrim(recipient_email))),
 role text not null check(role in('viewer','contributor')),token_sha256 text not null unique check(token_sha256~'^[a-f0-9]{64}$'),
 status text not null default 'pending' check(status in('pending','accepted','revoked')),revision integer not null default 1 check(revision>0),
 created_at timestamptz not null default now(),expires_at timestamptz not null,accepted_by uuid,grant_id uuid,accept_action_id uuid,
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_team_invites_page on public.pro_team_invites(owner_id,work_id,id);
create table if not exists public.pro_team_grants(
 id uuid primary key,owner_id uuid not null references public.profiles(id) on delete cascade,work_id text not null,
 -- Captured member identity must not block deletion of a collaborator account.
 member_user_id uuid not null,member_name text not null default '' check(length(member_name)<=160),
 role text not null check(role in('viewer','contributor')),active boolean not null default true,revision integer not null default 1 check(revision>0),
 source_invite_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(owner_id,work_id,member_user_id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_team_grants_member_page on public.pro_team_grants(member_user_id,id) where active;
create index if not exists pro_team_grants_owner_page on public.pro_team_grants(owner_id,work_id,id);
create table if not exists public.pro_team_comments(
 id uuid primary key,owner_id uuid not null,work_id text not null,actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),
 text text not null check(length(btrim(text)) between 1 and 1000),at timestamptz not null default now(),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_team_comments_page on public.pro_team_comments(owner_id,work_id,at desc,id desc);
create table if not exists public.pro_team_events(
 id uuid primary key default gen_random_uuid(),owner_id uuid not null,work_id text not null,actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),
 action_id uuid not null,action text not null check(action in('invite','accept','cancel_invite','set_role','revoke','comment','complete','reopen')),
 task_id uuid,title text,grant_id uuid,role text check(role in('viewer','contributor')),before_projected jsonb,after_projected jsonb,at timestamptz not null default now(),
 unique(actor_id,action_id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_team_events_page on public.pro_team_events(owner_id,work_id,at desc,id desc);
create table if not exists public.pro_team_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,owner_id uuid not null,work_id text not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create or replace function public.pro_team_name(p_actor uuid) returns text language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select left(btrim(full_name),160) from public.profiles where id=p_actor),'');
$$;
create or replace function public.pro_team_invite_json(p_invite public.pro_team_invites) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_invite.id,'ownerId',p_invite.owner_id,'workId',p_invite.work_id,'email',p_invite.recipient_email,'role',p_invite.role,
 'status',case when p_invite.status='pending' and p_invite.expires_at<=now() then 'expired' else p_invite.status end,
 'revision',p_invite.revision,'createdAt',p_invite.created_at,'expiresAt',p_invite.expires_at);
$$;
create or replace function public.pro_team_grant_json(p_grant public.pro_team_grants) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_grant.id,'ownerId',p_grant.owner_id,'workId',p_grant.work_id,'userId',p_grant.member_user_id,'displayName',p_grant.member_name,'role',p_grant.role,'active',p_grant.active,'revision',p_grant.revision);
$$;
create or replace function public.pro_team_shared_grant_json(p_grant public.pro_team_grants,p_actor uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_grant.id,'workId',p_grant.work_id,'role',p_grant.role,'revision',p_grant.revision,'ownerId',p_grant.owner_id,
 'ownerName',coalesce(nullif(left(btrim(p.business_name),160),''),public.pro_team_name(p_grant.owner_id)),
 'service',w.service,'stage',w.stage,'cancelled',coalesce(w.cancelled,false),'canContribute',p_actor=p_grant.owner_id or (p_grant.active and p_grant.role='contributor'))
 from public.pro_work w left join public.professionals p on p.profile_id=w.user_id where w.user_id=p_grant.owner_id and w.id=p_grant.work_id;
$$;
create or replace function public.pro_team_task_json(p_task public.pro_work_tasks) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_task.id,'title',p_task.title,'dueDate',case when p_task.due_date is null then null else to_char(p_task.due_date,'YYYY-MM-DD') end,'status',p_task.status,'revision',p_task.revision);
$$;
create or replace function public.pro_team_comment_json(p_comment public.pro_team_comments) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_comment.id,'actorId',p_comment.actor_id,'actorName',p_comment.actor_name,'text',p_comment.text,'at',p_comment.at);
$$;
create or replace function public.pro_team_context(p_actor uuid,p_grant uuid,p_write boolean default false) returns public.pro_team_grants
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into g from public.pro_team_grants where id=p_grant;
 if not found or not coalesce(public.pro_appointment_enabled(g.owner_id),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_actor<>g.owner_id and (g.member_user_id<>p_actor or not g.active or p_write and g.role<>'contributor') then raise exception 'Forbidden' using errcode='42501';end if;
 return g;
end $$;
create or replace function public.pro_team_owned_read(p_actor uuid,p_after text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id text;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null and (length(p_after) not between 1 and 160 or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_after)) then raise exception 'Invalid team work cursor' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'service',w.service,'stage',w.stage,'cancelled',coalesce(w.cancelled,false),'start',w.start) order by w.id),'[]'::jsonb) into items from (
  select id,service,stage,cancelled,start from public.pro_work where user_id=p_actor and (p_after is null or id>p_after) order by id limit 21
 ) w;
 if jsonb_array_length(items)>20 then cursor_id:=items->19->>'id';items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_owner_read(p_actor uuid,p_work text,p_kind text default 'members',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_kind is null or p_kind not in('members','invites') then raise exception 'Invalid team view' using errcode='22023';end if;
 if p_kind='members' then
  if p_after is not null and not exists(select 1 from public.pro_team_grants where owner_id=p_actor and work_id=p_work and id=p_after) then raise exception 'Invalid member cursor' using errcode='22023';end if;
  select coalesce(jsonb_agg(public.pro_team_grant_json(g::public.pro_team_grants) order by g.id),'[]'::jsonb) into items from (select * from public.pro_team_grants where owner_id=p_actor and work_id=p_work and (p_after is null or id>p_after) order by id limit 21) g;
 else
  if p_after is not null and not exists(select 1 from public.pro_team_invites where owner_id=p_actor and work_id=p_work and id=p_after) then raise exception 'Invalid invitation cursor' using errcode='22023';end if;
  select coalesce(jsonb_agg(public.pro_team_invite_json(i::public.pro_team_invites) order by i.id),'[]'::jsonb) into items from (select * from public.pro_team_invites where owner_id=p_actor and work_id=p_work and (p_after is null or id>p_after) order by id limit 21) i;
 end if;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_shared_read(p_actor uuid,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null and not exists(select 1 from public.pro_team_grants where id=p_after and member_user_id=p_actor and active and public.pro_appointment_enabled(owner_id)) then raise exception 'Invalid shared-work cursor' using errcode='22023';end if;
 select coalesce(jsonb_agg(public.pro_team_shared_grant_json(g::public.pro_team_grants,p_actor) order by g.id),'[]'::jsonb) into items from (select * from public.pro_team_grants where member_user_id=p_actor and active and public.pro_appointment_enabled(owner_id) and (p_after is null or id>p_after) order by id limit 21) g;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id,'canManage',coalesce(public.pro_appointment_enabled(p_actor),false));
end $$;
create or replace function public.pro_team_tasks_read(p_actor uuid,p_grant uuid,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;items jsonb;cursor_id uuid;cursor_due date;
begin
 g:=public.pro_team_context(p_actor,p_grant,false);
 if p_after is not null then select coalesce(due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and not archived and id=p_after;if not found then raise exception 'Invalid team task cursor' using errcode='22023';end if;end if;
 select coalesce(jsonb_agg(public.pro_team_task_json(t::public.pro_work_tasks) order by t.due_date asc nulls last,t.id),'[]'::jsonb) into items from (
  select * from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and not archived and (p_after is null or (coalesce(due_date,date '9999-12-31'),id)>(cursor_due,p_after)) order by due_date asc nulls last,id limit 21
 ) t;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('grant',public.pro_team_shared_grant_json(g,p_actor),'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_comments_read(p_actor uuid,p_grant uuid,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;items jsonb;cursor_id uuid;cursor_at timestamptz;
begin
 g:=public.pro_team_context(p_actor,p_grant,false);
 if p_after is not null then select at into cursor_at from public.pro_team_comments where owner_id=g.owner_id and work_id=g.work_id and id=p_after;if not found then raise exception 'Invalid team comment cursor' using errcode='22023';end if;end if;
 select coalesce(jsonb_agg(public.pro_team_comment_json(c::public.pro_team_comments) order by c.at desc,c.id desc),'[]'::jsonb) into items from (select * from public.pro_team_comments where owner_id=g.owner_id and work_id=g.work_id and (p_after is null or (at,id)<(cursor_at,p_after)) order by at desc,id desc limit 21) c;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('grant',public.pro_team_shared_grant_json(g,p_actor),'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_audit_read(p_actor uuid,p_work text,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;cursor_at timestamptz;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null then select at into cursor_at from public.pro_team_events where owner_id=p_actor and work_id=p_work and id=p_after;if not found then raise exception 'Invalid audit cursor' using errcode='22023';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'actionId',e.action_id,'actorId',e.actor_id,'actorName',e.actor_name,'action',e.action,'at',e.at,'taskId',e.task_id,'title',e.title,'grantId',e.grant_id,'role',e.role) order by e.at desc,e.id desc),'[]'::jsonb) into items from (
  select * from public.pro_team_events where owner_id=p_actor and work_id=p_work and (p_after is null or (at,id)<(cursor_at,p_after)) order by at desc,id desc limit 21
 ) e;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_mutate(p_actor uuid,p_input jsonb,p_verified_email text default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;owner uuid;wid text;gid uuid;iid uuid;tid uuid;rev integer;keys text[];email text;code_hash text;wanted_role text;body_text text;
 i public.pro_team_invites;g public.pro_team_grants;t public.pro_work_tasks;r public.pro_team_actions;c public.pro_team_comments;
 before_json jsonb;after_json jsonb;full_before jsonb;answer jsonb;actor_name text;event_task uuid;event_title text;event_grant uuid;event_role text;has_grant boolean;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid team operation' using errcode='22023';end if;
 act:=p_input->>'action';
 if act is null or act not in('invite','accept','cancel_invite','set_role','revoke','comment','complete','reopen') or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid team identity' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if act='invite' then
  if keys<>array['action','actionId','codeHash','email','role','workId'] or jsonb_typeof(p_input->'email') is distinct from 'string' or jsonb_typeof(p_input->'role') is distinct from 'string' then raise exception 'Invalid invitation fields' using errcode='22023';end if;
  email:=p_input->>'email';wanted_role:=p_input->>'role';
  if email<>lower(btrim(email)) or length(email)>254 or email !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or wanted_role not in('viewer','contributor') then raise exception 'Invalid invitation' using errcode='22023';end if;
 elsif act='accept' then
  if keys<>array['action','actionId','codeHash'] then raise exception 'Invalid acceptance fields' using errcode='22023';end if;
 elsif act='cancel_invite' then
  if keys<>array['action','actionId','inviteId','revision','workId'] or jsonb_typeof(p_input->'inviteId') is distinct from 'string' then raise exception 'Invalid invitation cancellation' using errcode='22023';end if;iid:=(p_input->>'inviteId')::uuid;
 elsif act in('set_role','revoke') then
  if (act='set_role' and keys<>array['action','actionId','grantId','revision','role','workId']) or (act='revoke' and keys<>array['action','actionId','grantId','revision','workId']) or jsonb_typeof(p_input->'grantId') is distinct from 'string' then raise exception 'Invalid member change' using errcode='22023';end if;
  gid:=(p_input->>'grantId')::uuid;
  if act='set_role' then wanted_role:=p_input->>'role';if jsonb_typeof(p_input->'role') is distinct from 'string' or wanted_role not in('viewer','contributor') then raise exception 'Invalid role' using errcode='22023';end if;end if;
 elsif act='comment' then
  if keys<>array['action','actionId','grantId','text'] or jsonb_typeof(p_input->'grantId') is distinct from 'string' or jsonb_typeof(p_input->'text') is distinct from 'string' then raise exception 'Invalid team comment' using errcode='22023';end if;
  gid:=(p_input->>'grantId')::uuid;body_text:=btrim(p_input->>'text');if length(body_text) not between 1 and 1000 then raise exception 'Invalid comment' using errcode='22023';end if;
 else
  if keys<>array['action','actionId','grantId','revision','taskId'] or jsonb_typeof(p_input->'grantId') is distinct from 'string' or jsonb_typeof(p_input->'taskId') is distinct from 'string' then raise exception 'Invalid team task action' using errcode='22023';end if;
  gid:=(p_input->>'grantId')::uuid;tid:=(p_input->>'taskId')::uuid;
 end if;
 if act in('invite','accept') then
  if jsonb_typeof(p_input->'codeHash') is distinct from 'string' or not coalesce((p_input->>'codeHash')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid code hash' using errcode='22023';end if;code_hash:=p_input->>'codeHash';
 end if;
 if act in('cancel_invite','set_role','revoke','complete','reopen') then
  if jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;rev:=(p_input->>'revision')::integer;
 end if;
 if act in('invite','cancel_invite','set_role','revoke') then
  if jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 then raise exception 'Invalid job identity' using errcode='22023';end if;owner:=p_actor;wid:=p_input->>'workId';
  if not coalesce(public.pro_appointment_enabled(owner),false) or not exists(select 1 from public.pro_work where user_id=owner and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 elsif act='accept' then
  select * into i from public.pro_team_invites where token_sha256=code_hash;
  if not found or p_verified_email is null or lower(btrim(p_verified_email)) is distinct from i.recipient_email or i.owner_id=p_actor or not coalesce(public.pro_appointment_enabled(i.owner_id),false) then raise exception 'Code unavailable' using errcode='42501';end if;owner:=i.owner_id;wid:=i.work_id;
 else
  g:=public.pro_team_context(p_actor,gid,true);owner:=g.owner_id;wid:=g.work_id;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-team-action:'||p_actor::text||':'||aid::text,0));
 -- Match the existing owner task writer: owner/work advisory, grant, task.
 -- Revocation and role changes take this identical lock before returning receipts.
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||owner::text||':'||wid,0));
 if act='accept' then
  select * into i from public.pro_team_invites where token_sha256=code_hash for update;
  if not found or i.owner_id<>owner or i.work_id<>wid or p_verified_email is null or lower(btrim(p_verified_email)) is distinct from i.recipient_email or not coalesce(public.pro_appointment_enabled(owner),false) then raise exception 'Code unavailable' using errcode='42501';end if;
  select * into g from public.pro_team_grants where owner_id=owner and work_id=wid and member_user_id=p_actor for update;has_grant:=found;
  if i.status='accepted' then
   if i.accepted_by is distinct from p_actor or i.accept_action_id is distinct from aid or not has_grant or not g.active or g.id is distinct from i.grant_id or g.source_invite_id is distinct from i.id then raise exception 'Code unavailable' using errcode='42501';end if;
  elsif i.status<>'pending' or i.expires_at<=now() or has_grant and g.active then raise exception 'Code unavailable' using errcode='42501';end if;
 elsif act='cancel_invite' then
  select * into i from public.pro_team_invites where id=iid and owner_id=owner and work_id=wid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
 elsif act in('set_role','revoke') then
  select * into g from public.pro_team_grants where id=gid and owner_id=owner and work_id=wid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
 elsif act in('comment','complete','reopen') then
  select * into g from public.pro_team_grants where id=gid for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  g:=public.pro_team_context(p_actor,gid,true);
  if g.owner_id<>owner or g.work_id<>wid then raise exception 'Forbidden' using errcode='42501';end if;
  if act in('complete','reopen') then
   select * into t from public.pro_work_tasks where owner_id=owner and work_id=wid and id=tid and not archived for update;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  end if;
 end if;
 if not coalesce(public.pro_appointment_enabled(owner),false) or not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 -- Never return an old committed result to a revoked/downgraded collaborator.
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=aid;
 if found then
  if r.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;return r.result;
 end if;
 actor_name:=public.pro_team_name(p_actor);
 if act='invite' then
  insert into public.pro_team_invites(id,owner_id,work_id,recipient_email,role,token_sha256,expires_at) values(aid,owner,wid,email,wanted_role,code_hash,now()+interval '72 hours') returning * into i;
  after_json:=jsonb_build_object('role',i.role,'status',i.status,'revision',i.revision);event_role:=i.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'invite',public.pro_team_invite_json(i));
 elsif act='accept' then
  if i.status<>'pending' then raise exception 'Code unavailable' using errcode='42501';end if;
  if has_grant then
   before_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);
   if g.revision>=2147483647 then raise exception 'Member revision exhausted' using errcode='54000';end if;
   update public.pro_team_grants set role=i.role,active=true,revision=revision+1,source_invite_id=i.id,member_name=actor_name,updated_at=now() where id=g.id returning * into g;
  else
   insert into public.pro_team_grants(id,owner_id,work_id,member_user_id,member_name,role,source_invite_id) values(gen_random_uuid(),owner,wid,p_actor,actor_name,i.role,i.id) returning * into g;
  end if;
  update public.pro_team_invites set status='accepted',revision=revision+1,accepted_by=p_actor,grant_id=g.id,accept_action_id=aid where id=i.id returning * into i;
  after_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);event_grant:=g.id;event_role:=g.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'grant',public.pro_team_grant_json(g));
 elsif act='cancel_invite' then
  if rev<>i.revision or i.status='accepted' then raise exception 'Invitation changed' using errcode='40001';end if;
  if i.status<>'pending' then raise exception 'Invitation unavailable' using errcode='22023';end if;
  before_json:=jsonb_build_object('role',i.role,'status',i.status,'revision',i.revision);
  update public.pro_team_invites set status='revoked',revision=revision+1 where id=i.id returning * into i;
  after_json:=jsonb_build_object('role',i.role,'status',i.status,'revision',i.revision);event_role:=i.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'invite',public.pro_team_invite_json(i));
 elsif act in('set_role','revoke') then
  if rev<>g.revision or not g.active then raise exception 'Member changed' using errcode='40001';end if;
  before_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);
  update public.pro_team_grants set role=case when act='set_role' then wanted_role else role end,active=act<>'revoke',revision=revision+1,updated_at=now() where id=g.id returning * into g;
  after_json:=jsonb_build_object('role',g.role,'active',g.active,'revision',g.revision);event_grant:=g.id;event_role:=g.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'grant',public.pro_team_grant_json(g));
 elsif act='comment' then
  insert into public.pro_team_comments(id,owner_id,work_id,actor_id,actor_name,text) values(aid,owner,wid,p_actor,actor_name,body_text) returning * into c;
  after_json:=jsonb_build_object('commentId',c.id);event_grant:=g.id;event_role:=g.role;
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'comment',public.pro_team_comment_json(c));
 else
  if rev<>t.revision then raise exception 'Task changed' using errcode='40001';end if;
  if act='complete' and t.status<>'open' or act='reopen' and t.status<>'done' then raise exception 'Invalid task transition' using errcode='22023';end if;
  full_before:=public.pro_work_task_json(t);before_json:=public.pro_team_task_json(t);
  update public.pro_work_tasks set status=case when act='complete' then 'done' else 'open' end,revision=revision+1,updated_at=now() where owner_id=owner and id=tid returning * into t;
  after_json:=public.pro_team_task_json(t);event_task:=t.id;event_title:=t.title;event_grant:=g.id;event_role:=g.role;
  -- owner_id below is storage scope, NOT the actor. Real actor is recorded in
  -- team_events/actions; never call the existing owner mutation as p_owner.
  insert into public.pro_work_task_history(owner_id,work_id,task_id,action_id,action,before_task,after_task) values(owner,wid,tid,aid,act,full_before,public.pro_work_task_json(t));
  answer:=jsonb_build_object('action',act,'ownerId',owner,'workId',wid,'task',after_json);
 end if;
 insert into public.pro_team_events(owner_id,work_id,actor_id,actor_name,action_id,action,task_id,title,grant_id,role,before_projected,after_projected)
 values(owner,wid,p_actor,actor_name,aid,act,event_task,event_title,event_grant,event_role,before_json,after_json);
 insert into public.pro_team_actions(actor_id,action_id,owner_id,work_id,input,result) values(p_actor,aid,owner,wid,p_input,answer);return answer;
end $$;
create or replace function public.pro_team_action_read(p_actor uuid,p_action uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_team_actions;i public.pro_team_invites;g public.pro_team_grants;t public.pro_work_tasks;c public.pro_team_comments;act text;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=p_action;if not found then return null;end if;act:=r.input->>'action';
 if act in('invite','cancel_invite','set_role','revoke') then
  if r.owner_id<>p_actor or not coalesce(public.pro_appointment_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=r.work_id) then raise exception 'Forbidden' using errcode='42501';end if;
  if act in('invite','cancel_invite') then
   select * into i from public.pro_team_invites where id=case when act='invite' then p_action else (r.input->>'inviteId')::uuid end and owner_id=p_actor and work_id=r.work_id;
   if not found then return null;end if;
   return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'invite',public.pro_team_invite_json(i));
  end if;
  select * into g from public.pro_team_grants where id=(r.input->>'grantId')::uuid and owner_id=p_actor and work_id=r.work_id;if not found then return null;end if;
  return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'grant',public.pro_team_grant_json(g));
 elsif act='accept' then
  select * into i from public.pro_team_invites where token_sha256=r.input->>'codeHash';
  if not found or i.status<>'accepted' or i.accepted_by is distinct from p_actor or i.accept_action_id is distinct from p_action then raise exception 'Forbidden' using errcode='42501';end if;
  g:=public.pro_team_context(p_actor,i.grant_id,false);
  if not g.active or g.source_invite_id<>i.id or g.owner_id<>r.owner_id or g.work_id<>r.work_id then raise exception 'Forbidden' using errcode='42501';end if;
  return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'grant',public.pro_team_grant_json(g));
 else
  g:=public.pro_team_context(p_actor,(r.input->>'grantId')::uuid,true);
  if g.owner_id<>r.owner_id or g.work_id<>r.work_id then raise exception 'Forbidden' using errcode='42501';end if;
  if act='comment' then
   select * into c from public.pro_team_comments where id=p_action and owner_id=r.owner_id and work_id=r.work_id and actor_id=p_actor;if not found then return null;end if;
   return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'comment',public.pro_team_comment_json(c));
  end if;
  select * into t from public.pro_work_tasks where owner_id=r.owner_id and work_id=r.work_id and id=(r.input->>'taskId')::uuid and not archived;
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  return jsonb_build_object('action',act,'ownerId',r.owner_id,'workId',r.work_id,'task',public.pro_team_task_json(t));
 end if;
end $$;
create or replace function public.pro_team_append_only() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Team comments, events and receipts are append-only' using errcode='23514';end $$;
drop trigger if exists pro_team_comments_immutable on public.pro_team_comments;
create trigger pro_team_comments_immutable before update on public.pro_team_comments for each row execute function public.pro_team_append_only();
drop trigger if exists pro_team_events_immutable on public.pro_team_events;
create trigger pro_team_events_immutable before update on public.pro_team_events for each row execute function public.pro_team_append_only();
drop trigger if exists pro_team_actions_immutable on public.pro_team_actions;
create trigger pro_team_actions_immutable before update on public.pro_team_actions for each row execute function public.pro_team_append_only();
alter table public.pro_team_invites enable row level security;alter table public.pro_team_grants enable row level security;alter table public.pro_team_comments enable row level security;alter table public.pro_team_events enable row level security;alter table public.pro_team_actions enable row level security;
revoke all on public.pro_team_invites,public.pro_team_grants,public.pro_team_comments,public.pro_team_events,public.pro_team_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_team_invites,public.pro_team_grants,public.pro_team_comments,public.pro_team_events,public.pro_team_actions to service_role;
revoke all on function public.pro_team_name(uuid),public.pro_team_invite_json(public.pro_team_invites),public.pro_team_grant_json(public.pro_team_grants),public.pro_team_shared_grant_json(public.pro_team_grants,uuid),public.pro_team_task_json(public.pro_work_tasks),public.pro_team_comment_json(public.pro_team_comments),public.pro_team_context(uuid,uuid,boolean),public.pro_team_owned_read(uuid,text),public.pro_team_owner_read(uuid,text,text,uuid),public.pro_team_shared_read(uuid,uuid),public.pro_team_tasks_read(uuid,uuid,uuid),public.pro_team_comments_read(uuid,uuid,uuid),public.pro_team_audit_read(uuid,text,uuid),public.pro_team_mutate(uuid,jsonb,text),public.pro_team_action_read(uuid,uuid),public.pro_team_append_only() from public,anon,authenticated;
grant execute on function public.pro_team_name(uuid),public.pro_team_invite_json(public.pro_team_invites),public.pro_team_grant_json(public.pro_team_grants),public.pro_team_shared_grant_json(public.pro_team_grants,uuid),public.pro_team_task_json(public.pro_work_tasks),public.pro_team_comment_json(public.pro_team_comments),public.pro_team_context(uuid,uuid,boolean),public.pro_team_owned_read(uuid,text),public.pro_team_owner_read(uuid,text,text,uuid),public.pro_team_shared_read(uuid,uuid),public.pro_team_tasks_read(uuid,uuid,uuid),public.pro_team_comments_read(uuid,uuid,uuid),public.pro_team_audit_read(uuid,text,uuid),public.pro_team_mutate(uuid,jsonb,text),public.pro_team_action_read(uuid,uuid) to service_role;
commit;

-- ===== team-task-assignments-local.sql =====
-- LOCAL PRO ONLY. Explicit account-bound task responsibility; no notifications.
begin;
create table if not exists public.pro_team_task_assignments(
 owner_id uuid not null,work_id text not null,task_id uuid not null,
 grant_id uuid not null,source_invite_id uuid not null,display_name text not null check(length(display_name)<=160),
 updated_at timestamptz not null default now(),primary key(owner_id,task_id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade,
 foreign key(owner_id,task_id) references public.pro_work_tasks(owner_id,id) on delete cascade
);
alter table public.pro_team_task_assignments drop constraint if exists pro_team_task_assignments_task_scope_fk;
alter table public.pro_team_task_assignments add constraint pro_team_task_assignments_task_scope_fk foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade;
create or replace function public.pro_team_grant_json(p_grant public.pro_team_grants) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_grant.id,'ownerId',p_grant.owner_id,'workId',p_grant.work_id,'userId',p_grant.member_user_id,'displayName',p_grant.member_name,'role',p_grant.role,'active',p_grant.active,'revision',p_grant.revision,
 'canAssign',p_grant.active and p_grant.role='contributor' and exists(select 1 from public.profiles p where p.id=p_grant.member_user_id and not coalesce(p.is_disabled,false)));
$$;
alter table public.pro_team_task_assignments enable row level security;
revoke all on public.pro_team_task_assignments from public,anon,authenticated;
grant select,insert,update,delete on public.pro_team_task_assignments to service_role;
alter table public.pro_team_events drop constraint if exists pro_team_events_action_check;
alter table public.pro_team_events add constraint pro_team_events_action_check check(action in('invite','accept','cancel_invite','set_role','revoke','comment','complete','reopen','assign'));
create or replace function public.pro_team_assignment_json(p_owner uuid,p_task uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('grantId',a.grant_id,'name',a.display_name,'active',coalesce(g.active and g.role='contributor' and g.source_invite_id=a.source_invite_id and exists(select 1 from public.profiles p where p.id=g.member_user_id and not coalesce(p.is_disabled,false)),false))
 from public.pro_team_task_assignments a left join public.pro_team_grants g on g.id=a.grant_id and g.owner_id=a.owner_id and g.work_id=a.work_id where a.owner_id=p_owner and a.task_id=p_task;
$$;
create or replace function public.pro_team_task_json(p_task public.pro_work_tasks) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_task.id,'title',p_task.title,'dueDate',case when p_task.due_date is null then null else to_char(p_task.due_date,'YYYY-MM-DD') end,'status',p_task.status,'revision',p_task.revision,'assignment',public.pro_team_assignment_json(p_task.owner_id,p_task.id));
$$;
create or replace function public.pro_team_task_assign(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;wid text;tid uuid;gid uuid;rev integer;keys text[];t public.pro_work_tasks;g public.pro_team_grants;r public.pro_team_actions;before_json jsonb;full_before jsonb;answer jsonb;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid assignment' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from array['action','actionId','assigneeGrantId','revision','taskId','workId'] or p_input->>'action' is distinct from 'assign' or jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'taskId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'assigneeGrantId') not in('string','null') or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) then raise exception 'Invalid assignment fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;tid:=(p_input->>'taskId')::uuid;gid:=(p_input->>'assigneeGrantId')::uuid;wid:=p_input->>'workId';
 if length(wid) not between 1 and 160 or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid assignment scope' using errcode='22023';end if;rev:=(p_input->>'revision')::integer;
 perform pg_advisory_xact_lock(hashtextextended('pro-team-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 if not coalesce(public.pro_appointment_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=wid) then raise exception 'Forbidden' using errcode='42501';end if;
 -- Shared receipt namespace also blocks reuse through the older team writer.
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=aid;
 if found then if r.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return r.result;end if;
 if gid is not null then
  select * into g from public.pro_team_grants where id=gid and owner_id=p_actor and work_id=wid for update;
  if not found or not g.active or g.role<>'contributor' or not exists(select 1 from public.profiles where id=g.member_user_id and not coalesce(is_disabled,false)) then raise exception 'Member unavailable' using errcode='40001';end if;
 end if;
 select * into t from public.pro_work_tasks where owner_id=p_actor and work_id=wid and id=tid and not archived for update;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if gid is not null and (not g.active or g.role<>'contributor' or not exists(select 1 from public.profiles where id=g.member_user_id and not coalesce(is_disabled,false))) then raise exception 'Member unavailable' using errcode='40001';end if;
 if t.revision<>rev then raise exception 'Task changed' using errcode='40001';end if;
 before_json:=public.pro_team_task_json(t);full_before:=public.pro_work_task_json(t);
 if gid is null then delete from public.pro_team_task_assignments where owner_id=p_actor and task_id=tid;
 else insert into public.pro_team_task_assignments(owner_id,work_id,task_id,grant_id,source_invite_id,display_name) values(p_actor,wid,tid,g.id,g.source_invite_id,g.member_name)
 on conflict(owner_id,task_id) do update set grant_id=excluded.grant_id,source_invite_id=excluded.source_invite_id,display_name=excluded.display_name,updated_at=now();end if;
 update public.pro_work_tasks set revision=revision+1,updated_at=now() where owner_id=p_actor and id=tid returning * into t;
 insert into public.pro_work_task_history(owner_id,work_id,task_id,action_id,action,before_task,after_task) values(p_actor,wid,tid,aid,'update',full_before,public.pro_work_task_json(t));
 insert into public.pro_team_events(owner_id,work_id,actor_id,actor_name,action_id,action,task_id,title,grant_id,before_projected,after_projected)
 values(p_actor,wid,p_actor,public.pro_team_name(p_actor),aid,'assign',tid,t.title,gid,before_json,public.pro_team_task_json(t));
 answer:=jsonb_build_object('action','assign','ownerId',p_actor,'workId',wid,'task',public.pro_team_task_json(t));
 insert into public.pro_team_actions(actor_id,action_id,owner_id,work_id,input,result) values(p_actor,aid,p_actor,wid,p_input,answer);return answer;
end $$;
create or replace function public.pro_team_assignment_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_team_actions;t public.pro_work_tasks;
begin
 select * into r from public.pro_team_actions where actor_id=p_actor and action_id=p_action;
 if not found or r.input->>'action'<>'assign' then return public.pro_team_action_read(p_actor,p_action);end if;
 if r.owner_id<>p_actor or not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into t from public.pro_work_tasks where owner_id=p_actor and work_id=r.work_id and id=(r.input->>'taskId')::uuid and not archived;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 return jsonb_build_object('action','assign','ownerId',p_actor,'workId',r.work_id,'task',public.pro_team_task_json(t));
end $$;
revoke all on function public.pro_team_assignment_json(uuid,uuid),public.pro_team_task_assign(uuid,jsonb),public.pro_team_assignment_action_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_team_assignment_json(uuid,uuid),public.pro_team_task_assign(uuid,jsonb),public.pro_team_assignment_action_read(uuid,uuid) to service_role;
create or replace function public.pro_team_audit_read(p_actor uuid,p_work text,p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;cursor_at timestamptz;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_after is not null then select at into cursor_at from public.pro_team_events where owner_id=p_actor and work_id=p_work and id=p_after;if not found then raise exception 'Invalid audit cursor' using errcode='22023';end if;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'actionId',e.action_id,'actorId',e.actor_id,'actorName',e.actor_name,'action',e.action,'at',e.at,'taskId',e.task_id,'title',e.title,'grantId',e.grant_id,'role',e.role,'assignmentBefore',e.before_projected->'assignment','assignmentAfter',e.after_projected->'assignment') order by e.at desc,e.id desc),'[]'::jsonb) into items from (
  select * from public.pro_team_events where owner_id=p_actor and work_id=p_work and (p_after is null or (at,id)<(cursor_at,p_after)) order by at desc,id desc limit 21
 ) e;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('workId',p_work,'items',items,'nextCursor',cursor_id);
end $$;
commit;

-- ===== team-task-discussion-local.sql =====
-- LOCAL PRO ONLY. Task-scoped team discussion; isolated private storage, no sends.
begin;
create table if not exists public.pro_team_task_comments(
 id uuid primary key,owner_id uuid not null,work_id text not null,task_id uuid not null,
 actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),text text not null check(length(btrim(text)) between 1 and 1000),at timestamptz not null default now(),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade
);
create index if not exists pro_team_task_comments_page on public.pro_team_task_comments(owner_id,work_id,task_id,at desc,id desc);
create table if not exists public.pro_team_task_comment_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,owner_id uuid not null,work_id text not null,task_id uuid not null,
 grant_id uuid not null,source_invite_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default now(),primary key(actor_id,action_id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade
);
create table if not exists public.pro_team_task_files(
 id uuid primary key,owner_id uuid not null,work_id text not null,task_id uuid not null,
 actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),grant_id uuid not null,source_invite_id uuid not null,
 source_name text not null check(length(source_name) between 1 and 160 and source_name !~ '[[:cntrl:]/]' and position(chr(92) in source_name)=0),
 name text not null check(length(name) between 1 and 160 and name !~ '[[:cntrl:]/]' and position(chr(92) in name)=0),
 mime_type text not null check(mime_type in('image/jpeg','application/pdf')),raw_sha256 text not null check(raw_sha256~'^[a-f0-9]{64}$'),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),
 size_bytes integer not null check(size_bytes between 1 and 20971520),object_path text not null unique,ready boolean not null default false,created_at timestamptz not null default now(),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade,
 check(mime_type<>'image/jpeg' or size_bytes<=20971520),
 check(object_path=owner_id::text||'/'||id::text||case when mime_type='application/pdf' then '.pdf' else '.jpg' end),
 check(right(name,4)=case when mime_type='application/pdf' then '.pdf' else '.jpg' end)
);
create index if not exists pro_team_task_files_page on public.pro_team_task_files(owner_id,work_id,task_id,created_at desc,id desc);
create table if not exists public.pro_team_task_file_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,file_id uuid not null references public.pro_team_task_files(id) on delete cascade,input jsonb not null,result jsonb,at timestamptz not null default now(),primary key(actor_id,file_id)
);
create or replace function public.pro_team_task_comment_json(p_comment public.pro_team_task_comments) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_comment.id,'actorId',p_comment.actor_id,'actorName',p_comment.actor_name,'text',p_comment.text,'at',p_comment.at);
$$;
create or replace function public.pro_team_task_file_json(p_file public.pro_team_task_files) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_file.id,'taskId',p_file.task_id,'name',p_file.name,'mimeType',p_file.mime_type,'sizeBytes',p_file.size_bytes,'sha256',p_file.sha256,'ready',p_file.ready,'actorId',p_file.actor_id,'actorName',p_file.actor_name,'createdAt',p_file.created_at);
$$;
create or replace function public.pro_team_task_discussion_context(p_actor uuid,p_grant uuid,p_task uuid,p_write boolean default false) returns public.pro_team_grants language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;
begin
 g:=public.pro_team_context(p_actor,p_grant,p_write);
 if not exists(select 1 from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=p_task and not archived) then raise exception 'Task unavailable' using errcode='42501';end if;
 return g;
end $$;
create or replace function public.pro_team_task_discussion_read(p_actor uuid,p_grant uuid,p_task uuid,p_kind text,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;t public.pro_work_tasks;items jsonb;cursor_at timestamptz;cursor_id uuid;
begin
 g:=public.pro_team_task_discussion_context(p_actor,p_grant,p_task,false);
 select * into t from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=p_task;
 if p_kind='comments' then
  if p_after is not null then select at into cursor_at from public.pro_team_task_comments where owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and id=p_after;if not found then raise exception 'Invalid comment cursor' using errcode='22023';end if;end if;
  select coalesce(jsonb_agg(public.pro_team_task_comment_json(c::public.pro_team_task_comments) order by c.at desc,c.id desc),'[]'::jsonb) into items from(select * from public.pro_team_task_comments where owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and (p_after is null or (at,id)<(cursor_at,p_after)) order by at desc,id desc limit 21)c;
 elsif p_kind='files' then
  if p_after is not null then select created_at into cursor_at from public.pro_team_task_files where owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and id=p_after and ready;if not found then raise exception 'Invalid file cursor' using errcode='22023';end if;end if;
  select coalesce(jsonb_agg(public.pro_team_task_file_json(f::public.pro_team_task_files) order by f.created_at desc,f.id desc),'[]'::jsonb) into items from(select * from public.pro_team_task_files where owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and ready and (p_after is null or(created_at,id)<(cursor_at,p_after)) order by created_at desc,id desc limit 21)f;
 else raise exception 'Invalid discussion view' using errcode='22023';end if;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('grant',public.pro_team_shared_grant_json(g,p_actor),'task',public.pro_team_task_json(t),'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_task_comment_write(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;r public.pro_team_task_comment_actions;c public.pro_team_task_comments;gid uuid;tid uuid;aid uuid;keys text[];body text;answer jsonb;
begin
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if keys is distinct from array['action','actionId','grantId','taskId','text'] or p_input->>'action' is distinct from 'comment' or jsonb_typeof(p_input->'text') is distinct from 'string' then raise exception 'Invalid task comment' using errcode='22023';end if;
 gid:=(p_input->>'grantId')::uuid;tid:=(p_input->>'taskId')::uuid;aid:=(p_input->>'actionId')::uuid;body:=btrim(p_input->>'text');
 if gid is null or tid is null or aid is null or length(body) not between 1 and 1000 then raise exception 'Invalid comment identity' using errcode='22023';end if;
 g:=public.pro_team_task_discussion_context(p_actor,gid,tid,true);
 perform pg_advisory_xact_lock(hashtextextended('pro-team-task-comment:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||g.owner_id::text||':'||g.work_id,0));
 perform 1 from public.pro_team_grants where id=gid for update;
 perform 1 from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=tid for update;
 g:=public.pro_team_task_discussion_context(p_actor,gid,tid,true);
 select * into r from public.pro_team_task_comment_actions where actor_id=p_actor and action_id=aid;
 if found then
  if r.input is distinct from p_input then raise exception 'Comment identity reused' using errcode='22023';end if;
  if p_actor<>g.owner_id and r.source_invite_id<>g.source_invite_id then raise exception 'Access changed' using errcode='42501';end if;
  return r.result;
 end if;
 insert into public.pro_team_task_comments(id,owner_id,work_id,task_id,actor_id,actor_name,text) values(aid,g.owner_id,g.work_id,tid,p_actor,public.pro_team_name(p_actor),body) returning * into c;
 answer:=jsonb_build_object('comment',public.pro_team_task_comment_json(c));
 insert into public.pro_team_task_comment_actions(actor_id,action_id,owner_id,work_id,task_id,grant_id,source_invite_id,input,result) values(p_actor,aid,g.owner_id,g.work_id,tid,gid,g.source_invite_id,p_input,answer);return answer;
end $$;
create or replace function public.pro_team_task_comment_proof(p_actor uuid,p_grant uuid,p_task uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;r public.pro_team_task_comment_actions;
begin
 g:=public.pro_team_task_discussion_context(p_actor,p_grant,p_task,true);
 select * into r from public.pro_team_task_comment_actions where actor_id=p_actor and action_id=p_action and owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and grant_id=p_grant;
 if not found then return null;end if;
 if p_actor<>g.owner_id and r.source_invite_id<>g.source_invite_id then raise exception 'Access changed' using errcode='42501';end if;return r.result;
end $$;
create or replace function public.pro_team_task_file_read(p_actor uuid,p_grant uuid,p_task uuid,p_file uuid,p_proof boolean default false,p_binary boolean default false) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;f public.pro_team_task_files;
begin
 g:=public.pro_team_task_discussion_context(p_actor,p_grant,p_task,p_proof);
 select * into f from public.pro_team_task_files where id=p_file and owner_id=g.owner_id and work_id=g.work_id and task_id=p_task;
 if not found then return null;end if;
 if p_proof and (f.actor_id<>p_actor or f.grant_id<>p_grant or p_actor<>g.owner_id and f.source_invite_id<>g.source_invite_id) then raise exception 'Access changed' using errcode='42501';end if;
 if not p_proof and not f.ready then return null;end if;
 if p_binary then
  if not f.ready then return null;end if;
  return jsonb_build_object('objectPath',f.object_path,'name',f.name,'mimeType',f.mime_type,'sizeBytes',f.size_bytes,'sha256',f.sha256);
 end if;return jsonb_build_object('file',public.pro_team_task_file_json(f));
end $$;
create or replace function public.pro_team_task_file_reserve(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;f public.pro_team_task_files;r public.pro_team_task_file_actions;gid uuid;tid uuid;fid uuid;keys text[];size integer;mime text;path text;
begin
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if keys is distinct from array['fileId','grantId','mimeType','name','rawSha256','sha256','sizeBytes','sourceName','taskId'] then raise exception 'Invalid upload fields' using errcode='22023';end if;
 gid:=(p_input->>'grantId')::uuid;tid:=(p_input->>'taskId')::uuid;fid:=(p_input->>'fileId')::uuid;mime:=p_input->>'mimeType';
 if gid is null or tid is null or fid is null or mime not in('image/jpeg','application/pdf') or jsonb_typeof(p_input->'sizeBytes') is distinct from 'number' or not coalesce((p_input->>'sizeBytes')~'^[0-9]{1,8}$',false) or not coalesce((p_input->>'rawSha256')~'^[a-f0-9]{64}$',false) or not coalesce((p_input->>'sha256')~'^[a-f0-9]{64}$',false) then raise exception 'Invalid upload metadata' using errcode='22023';end if;
 size:=(p_input->>'sizeBytes')::integer;if size not between 1 and 20971520 or mime='image/jpeg' and size>20971520 then raise exception 'Invalid upload size' using errcode='22023';end if;
 if jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'sourceName') is distinct from 'string' then raise exception 'Invalid filename' using errcode='22023';end if;
 g:=public.pro_team_task_discussion_context(p_actor,gid,tid,true);
 perform pg_advisory_xact_lock(hashtextextended('pro-team-task-file:'||fid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||g.owner_id::text||':'||g.work_id,0));
 perform 1 from public.pro_team_grants where id=gid for update;
 perform 1 from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=tid for update;
 g:=public.pro_team_task_discussion_context(p_actor,gid,tid,true);
 select * into r from public.pro_team_task_file_actions where actor_id=p_actor and file_id=fid;
 if found then
  if r.input is distinct from p_input then raise exception 'Upload identity reused' using errcode='22023';end if;
  select * into f from public.pro_team_task_files where id=fid;
  if not found or f.owner_id<>g.owner_id or f.work_id<>g.work_id or f.task_id<>tid or f.grant_id<>gid or p_actor<>g.owner_id and f.source_invite_id<>g.source_invite_id then raise exception 'Access changed' using errcode='42501';end if;
  return jsonb_build_object('file',public.pro_team_task_file_json(f),'objectPath',f.object_path);
 end if;
 if exists(select 1 from public.pro_team_task_files where id=fid) then raise exception 'Upload identity unavailable' using errcode='42501';end if;
 if (select count(*) from public.pro_team_task_files where owner_id=g.owner_id and work_id=g.work_id and task_id=tid)>=100 then raise exception 'Task file limit reached' using errcode='54000';end if;
 path:=g.owner_id::text||'/'||fid::text||case when mime='application/pdf' then '.pdf' else '.jpg' end;
 insert into public.pro_team_task_files(id,owner_id,work_id,task_id,actor_id,actor_name,grant_id,source_invite_id,source_name,name,mime_type,raw_sha256,sha256,size_bytes,object_path)
 values(fid,g.owner_id,g.work_id,tid,p_actor,public.pro_team_name(p_actor),gid,g.source_invite_id,p_input->>'sourceName',p_input->>'name',mime,p_input->>'rawSha256',p_input->>'sha256',size,path) returning * into f;
 insert into public.pro_team_task_file_actions(actor_id,file_id,input) values(p_actor,fid,p_input);
 return jsonb_build_object('file',public.pro_team_task_file_json(f),'objectPath',f.object_path);
end $$;
create or replace function public.pro_team_task_file_ready(p_actor uuid,p_grant uuid,p_task uuid,p_file uuid,p_sha256 text) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;f public.pro_team_task_files;r public.pro_team_task_file_actions;answer jsonb;
begin
 g:=public.pro_team_task_discussion_context(p_actor,p_grant,p_task,true);
 perform pg_advisory_xact_lock(hashtextextended('pro-team-task-file:'||p_file::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||g.owner_id::text||':'||g.work_id,0));
 perform 1 from public.pro_team_grants where id=p_grant for update;
 perform 1 from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=p_task for update;
 g:=public.pro_team_task_discussion_context(p_actor,p_grant,p_task,true);
 select * into f from public.pro_team_task_files where id=p_file and actor_id=p_actor and owner_id=g.owner_id and work_id=g.work_id and task_id=p_task and grant_id=p_grant for update;
 if not found or p_actor<>g.owner_id and f.source_invite_id<>g.source_invite_id then raise exception 'Access changed' using errcode='42501';end if;
 if f.sha256 is distinct from p_sha256 then raise exception 'Upload hash changed' using errcode='22023';end if;
 select * into r from public.pro_team_task_file_actions where actor_id=p_actor and file_id=p_file for update;if not found then raise exception 'Upload not reserved' using errcode='42501';end if;
 if r.result is not null then return r.result;end if;
 update public.pro_team_task_files set ready=true where id=p_file returning * into f;
 answer:=jsonb_build_object('file',public.pro_team_task_file_json(f));update public.pro_team_task_file_actions set result=answer where actor_id=p_actor and file_id=p_file;return answer;
end $$;
create or replace function public.pro_team_task_file_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin if (to_jsonb(new)-'ready') is distinct from (to_jsonb(old)-'ready') or old.ready or not new.ready then raise exception 'Task files are immutable' using errcode='23514';end if;return new;end $$;
create or replace function public.pro_team_task_file_receipt_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin if old.result is not null or new.result is null or (to_jsonb(new)-'result') is distinct from (to_jsonb(old)-'result') then raise exception 'Upload receipts are immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_team_task_comments_immutable on public.pro_team_task_comments;
create trigger pro_team_task_comments_immutable before update on public.pro_team_task_comments for each row execute function public.pro_team_append_only();
drop trigger if exists pro_team_task_comment_actions_immutable on public.pro_team_task_comment_actions;
create trigger pro_team_task_comment_actions_immutable before update on public.pro_team_task_comment_actions for each row execute function public.pro_team_append_only();
drop trigger if exists pro_team_task_files_immutable on public.pro_team_task_files;
create trigger pro_team_task_files_immutable before update on public.pro_team_task_files for each row execute function public.pro_team_task_file_immutable();
drop trigger if exists pro_team_task_file_actions_immutable on public.pro_team_task_file_actions;
create trigger pro_team_task_file_actions_immutable before update on public.pro_team_task_file_actions for each row execute function public.pro_team_task_file_receipt_immutable();
alter table public.pro_team_task_comments enable row level security;alter table public.pro_team_task_comment_actions enable row level security;alter table public.pro_team_task_files enable row level security;alter table public.pro_team_task_file_actions enable row level security;
revoke all on public.pro_team_task_comments,public.pro_team_task_comment_actions,public.pro_team_task_files,public.pro_team_task_file_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_team_task_comments,public.pro_team_task_comment_actions,public.pro_team_task_files,public.pro_team_task_file_actions to service_role;
revoke all on function public.pro_team_task_comment_json(public.pro_team_task_comments),public.pro_team_task_file_json(public.pro_team_task_files),public.pro_team_task_discussion_context(uuid,uuid,uuid,boolean),public.pro_team_task_discussion_read(uuid,uuid,uuid,text,uuid),public.pro_team_task_comment_write(uuid,jsonb),public.pro_team_task_comment_proof(uuid,uuid,uuid,uuid),public.pro_team_task_file_read(uuid,uuid,uuid,uuid,boolean,boolean),public.pro_team_task_file_reserve(uuid,jsonb),public.pro_team_task_file_ready(uuid,uuid,uuid,uuid,text),public.pro_team_task_file_immutable(),public.pro_team_task_file_receipt_immutable() from public,anon,authenticated;
grant execute on function public.pro_team_task_comment_json(public.pro_team_task_comments),public.pro_team_task_file_json(public.pro_team_task_files),public.pro_team_task_discussion_context(uuid,uuid,uuid,boolean),public.pro_team_task_discussion_read(uuid,uuid,uuid,text,uuid),public.pro_team_task_comment_write(uuid,jsonb),public.pro_team_task_comment_proof(uuid,uuid,uuid,uuid),public.pro_team_task_file_read(uuid,uuid,uuid,uuid,boolean,boolean),public.pro_team_task_file_reserve(uuid,jsonb),public.pro_team_task_file_ready(uuid,uuid,uuid,uuid,text) to service_role;
do $$ begin
 if to_regclass('storage.buckets') is not null then
  insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('pro-team-task-files','pro-team-task-files',false,20971520,array['image/jpeg','application/pdf']) on conflict(id) do update set file_size_limit=excluded.file_size_limit;
  if not exists(select 1 from storage.buckets where id='pro-team-task-files' and not public and file_size_limit=20971520 and cardinality(allowed_mime_types)=2 and allowed_mime_types @> array['image/jpeg','application/pdf']) then raise exception 'Team task file bucket configuration mismatch';end if;
 end if;
 if to_regclass('storage.objects') is not null then
  execute 'drop policy if exists pro_team_task_files_no_direct on storage.objects';
  execute 'create policy pro_team_task_files_no_direct on storage.objects as restrictive for all to anon,authenticated using(bucket_id <> ''pro-team-task-files'') with check(bucket_id <> ''pro-team-task-files'')';
 end if;
end $$;
commit;

-- ===== team-task-mentions-local.sql =====
-- LOCAL PRO ONLY. Explicit task mentions and an isolated internal inbox. NO sends/outbox.
begin;
create unique index if not exists pro_team_task_comments_scope_id on public.pro_team_task_comments(owner_id,work_id,task_id,id);
create table if not exists public.pro_team_task_mentions(
 comment_id uuid not null references public.pro_team_task_comments(id) on delete cascade,recipient_id uuid not null,
 owner_id uuid not null,work_id text not null,task_id uuid not null,name text not null check(length(name)<=160),
 recipient_grant_id uuid,recipient_source_invite_id uuid,primary key(comment_id,recipient_id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade,
 check((recipient_grant_id is null)=(recipient_source_invite_id is null)),
 foreign key(owner_id,work_id,task_id,comment_id) references public.pro_team_task_comments(owner_id,work_id,task_id,id) on delete cascade
);
create table if not exists public.pro_team_task_mention_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 comment_id uuid not null references public.pro_team_task_comments(id) on delete cascade,input jsonb not null,result jsonb not null,
 primary key(actor_id,action_id)
);
create table if not exists public.pro_team_task_notices(
 id uuid primary key default gen_random_uuid(),recipient_id uuid not null,owner_id uuid not null,work_id text not null,task_id uuid not null,
 comment_id uuid not null references public.pro_team_task_comments(id) on delete cascade,actor_id uuid not null,actor_name text not null check(length(actor_name)<=160),
 recipient_grant_id uuid,recipient_source_invite_id uuid,open_grant_id uuid not null,
 task_title text not null check(length(task_title) between 1 and 160),service text not null check(length(service)<=160),created_at timestamptz not null default now(),read_at timestamptz,
 unique(comment_id,recipient_id),foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade,
 check((recipient_grant_id is null)=(recipient_source_invite_id is null)),
 foreign key(owner_id,work_id,task_id,comment_id) references public.pro_team_task_comments(owner_id,work_id,task_id,id) on delete cascade
);
create index if not exists pro_team_task_notices_page on public.pro_team_task_notices(recipient_id,created_at desc,id desc);
create table if not exists public.pro_team_task_notice_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,notice_id uuid not null references public.pro_team_task_notices(id) on delete cascade,input jsonb not null,result jsonb not null,
 primary key(actor_id,action_id)
);
create or replace function public.pro_team_task_comment_json(p_comment public.pro_team_task_comments) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_comment.id,'actorId',p_comment.actor_id,'actorName',p_comment.actor_name,'text',p_comment.text,'at',p_comment.at,'mentions',coalesce((select jsonb_agg(jsonb_build_object('userId',m.recipient_id,'name',m.name) order by m.recipient_id) from public.pro_team_task_mentions m where m.comment_id=p_comment.id),'[]'::jsonb));
$$;
create or replace function public.pro_team_task_mention_targets(p_actor uuid,p_grant uuid,p_task uuid,p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;items jsonb;cursor_id uuid;
begin
 g:=public.pro_team_task_discussion_context(p_actor,p_grant,p_task,true);
 if p_after is not null and not (
  p_after=g.owner_id and p_after<>p_actor and exists(select 1 from public.profiles where id=p_after and not coalesce(is_disabled,false))
  or exists(select 1 from public.pro_team_grants mg join public.profiles p on p.id=mg.member_user_id where mg.owner_id=g.owner_id and mg.work_id=g.work_id and mg.active and p.id=p_after and p.id<>p_actor and not coalesce(p.is_disabled,false))
 ) then raise exception 'Invalid mention target cursor' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('userId',x.user_id,'grantId',x.grant_id,'sourceInviteId',x.source_id,'name',x.name) order by x.user_id),'[]'::jsonb) into items from(
 select * from(
 select p.id user_id,null::uuid grant_id,null::uuid source_id,public.pro_team_name(p.id) name from public.profiles p where p.id=g.owner_id and not coalesce(p.is_disabled,false) and p.id<>p_actor
 union all select p.id,mg.id,mg.source_invite_id,mg.member_name from public.pro_team_grants mg join public.profiles p on p.id=mg.member_user_id where mg.owner_id=g.owner_id and mg.work_id=g.work_id and mg.active and not coalesce(p.is_disabled,false) and p.id<>p_actor
 ) targets where p_after is null or user_id>p_after order by user_id limit 21)x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'userId')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_team_task_comment_with_mentions(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare g public.pro_team_grants;target public.pro_team_grants;r public.pro_team_task_mention_actions;oldr public.pro_team_task_comment_actions;c public.pro_team_task_comments;t public.pro_work_tasks;aid uuid;tid uuid;gid uuid;m jsonb;uid uuid;mgid uuid;source uuid;nm text;answer jsonb;seen uuid[]:=array[]::uuid[];keys text[];
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid comment' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if keys is distinct from array['action','actionId','grantId','mentions','taskId','text'] and keys is distinct from array['action','actionId','grantId','taskId','text'] then raise exception 'Invalid mention comment fields' using errcode='22023';end if;
 if p_input ? 'mentions' and (jsonb_typeof(p_input->'mentions') is distinct from 'array' or jsonb_array_length(p_input->'mentions')>5) then raise exception 'Invalid mentions' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;tid:=(p_input->>'taskId')::uuid;gid:=(p_input->>'grantId')::uuid;
 if aid is null or tid is null or gid is null then raise exception 'Invalid comment identity' using errcode='22023';end if;
 g:=public.pro_team_task_discussion_context(p_actor,gid,tid,true);
 perform pg_advisory_xact_lock(hashtextextended('pro-team-task-comment:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||g.owner_id::text||':'||g.work_id,0));
 perform 1 from public.pro_team_grants where id=gid for update;
 perform 1 from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=tid for update;
 g:=public.pro_team_task_discussion_context(p_actor,gid,tid,true);
 -- Calling the established writer checks current author/generation before receipt.
 select * into oldr from public.pro_team_task_comment_actions where actor_id=p_actor and action_id=aid;
 select * into r from public.pro_team_task_mention_actions where actor_id=p_actor and action_id=aid;
 if found then
  perform public.pro_team_task_comment_write(p_actor,p_input-'mentions');
  if r.input is distinct from p_input then raise exception 'Comment identity reused' using errcode='22023';end if;return r.result;
 end if;
 if oldr.action_id is not null and p_input ? 'mentions' then raise exception 'Legacy comment identity reused' using errcode='22023';end if;
 answer:=public.pro_team_task_comment_write(p_actor,p_input-'mentions');
 if oldr.action_id is not null then return answer;end if;
 select * into c from public.pro_team_task_comments where id=aid;
 select * into t from public.pro_work_tasks where owner_id=g.owner_id and work_id=g.work_id and id=tid;
 for m in select value from jsonb_array_elements(coalesce(p_input->'mentions','[]'::jsonb)) loop
  select array_agg(key order by key) into keys from jsonb_object_keys(m)key;
  if keys is distinct from array['grantId','sourceInviteId','userId'] then raise exception 'Invalid mention target' using errcode='22023';end if;
  uid:=(m->>'userId')::uuid;mgid:=(m->>'grantId')::uuid;source:=(m->>'sourceInviteId')::uuid;
  if uid is null or uid=p_actor or uid=any(seen) then raise exception 'Invalid mention identity' using errcode='22023';end if;seen:=array_append(seen,uid);
  if uid=g.owner_id then
   if mgid is not null or source is not null then raise exception 'Mention target changed' using errcode='40001';end if;nm:=public.pro_team_name(uid);
  else
   select * into target from public.pro_team_grants where id=mgid and owner_id=g.owner_id and work_id=g.work_id and member_user_id=uid for update;
   if not found or not target.active or target.source_invite_id is distinct from source then raise exception 'Mention target changed' using errcode='40001';end if;nm:=target.member_name;
  end if;
  if not exists(select 1 from public.profiles where id=uid and not coalesce(is_disabled,false)) then raise exception 'Mention target changed' using errcode='40001';end if;
  insert into public.pro_team_task_mentions(comment_id,recipient_id,owner_id,work_id,task_id,name,recipient_grant_id,recipient_source_invite_id) values(aid,uid,g.owner_id,g.work_id,tid,nm,mgid,source);
  insert into public.pro_team_task_notices(recipient_id,owner_id,work_id,task_id,comment_id,actor_id,actor_name,recipient_grant_id,recipient_source_invite_id,open_grant_id,task_title,service)
  select uid,g.owner_id,g.work_id,tid,aid,p_actor,c.actor_name,mgid,source,coalesce(mgid,gid),t.title,w.service from public.pro_work w where w.user_id=g.owner_id and w.id=g.work_id;
 end loop;
 -- Recheck author and every captured recipient after all target locks/checks.
 g:=public.pro_team_task_discussion_context(p_actor,gid,tid,true);
 if exists(select 1 from unnest(seen) recipient where not exists(select 1 from public.profiles p where p.id=recipient and not coalesce(p.is_disabled,false))) then raise exception 'Mention target changed' using errcode='40001';end if;
 answer:=jsonb_build_object('comment',public.pro_team_task_comment_json(c));
 insert into public.pro_team_task_mention_actions(actor_id,action_id,comment_id,input,result) values(p_actor,aid,aid,p_input,answer);return answer;
end $$;
create or replace function public.pro_team_task_mention_comment_proof(p_actor uuid,p_grant uuid,p_task uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare answer jsonb;r public.pro_team_task_mention_actions;
begin
 answer:=public.pro_team_task_comment_proof(p_actor,p_grant,p_task,p_action);if answer is null then return null;end if;
 select * into r from public.pro_team_task_mention_actions where actor_id=p_actor and action_id=p_action;
 if found then return r.result;end if;return answer;
end $$;
create or replace function public.pro_team_task_notice_allowed(p_actor uuid,p_notice public.pro_team_task_notices) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 select p_notice.recipient_id=p_actor and exists(select 1 from public.profiles p where p.id=p_actor and not coalesce(p.is_disabled,false)) and coalesce(public.pro_appointment_enabled(p_notice.owner_id),false)
 and exists(select 1 from public.pro_work_tasks t where t.owner_id=p_notice.owner_id and t.work_id=p_notice.work_id and t.id=p_notice.task_id and not t.archived)
 and (p_actor=p_notice.owner_id or exists(select 1 from public.pro_team_grants g where g.id=p_notice.recipient_grant_id and g.owner_id=p_notice.owner_id and g.work_id=p_notice.work_id and g.member_user_id=p_actor and g.active and g.source_invite_id=p_notice.recipient_source_invite_id));
$$;
create or replace function public.pro_team_task_notice_json(p_notice public.pro_team_task_notices) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_notice.id,'ownerId',p_notice.owner_id,'workId',p_notice.work_id,'taskId',p_notice.task_id,'commentId',p_notice.comment_id,'actorId',p_notice.actor_id,'actorName',p_notice.actor_name,'taskTitle',p_notice.task_title,'service',p_notice.service,'createdAt',p_notice.created_at,'readAt',p_notice.read_at);
$$;
create or replace function public.pro_team_task_notice_inbox(p_actor uuid,p_status text default 'all',p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;cursor_id uuid;cursor_at timestamptz;unread_count bigint;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('all','unread') then raise exception 'Invalid inbox status' using errcode='22023';end if;
 if p_after is not null then select created_at into cursor_at from public.pro_team_task_notices n where n.id=p_after and public.pro_team_task_notice_allowed(p_actor,n) and(p_status='all' or n.read_at is null);if not found then raise exception 'Invalid notice cursor' using errcode='22023';end if;end if;
 select count(*) into unread_count from public.pro_team_task_notices n where n.recipient_id=p_actor and n.read_at is null and public.pro_team_task_notice_allowed(p_actor,n);
 select coalesce(jsonb_agg(public.pro_team_task_notice_json(n::public.pro_team_task_notices) order by n.created_at desc,n.id desc),'[]'::jsonb) into items from(
 select * from public.pro_team_task_notices n where n.recipient_id=p_actor and public.pro_team_task_notice_allowed(p_actor,n) and(p_status='all' or n.read_at is null) and(p_after is null or(n.created_at,n.id)<(cursor_at,p_after)) order by n.created_at desc,n.id desc limit 21)n;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',cursor_id,'unreadCount',unread_count);
end $$;
create or replace function public.pro_team_task_notice_open(p_actor uuid,p_notice uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare n public.pro_team_task_notices;
begin
 select * into n from public.pro_team_task_notices where id=p_notice;
 if not found or not public.pro_team_task_notice_allowed(p_actor,n) then raise exception 'Notice unavailable' using errcode='42501';end if;
 perform public.pro_team_task_discussion_context(p_actor,n.open_grant_id,n.task_id,false);
 return jsonb_build_object('grantId',n.open_grant_id,'taskId',n.task_id);
end $$;
create or replace function public.pro_team_task_notice_mark_read(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare n public.pro_team_task_notices;r public.pro_team_task_notice_actions;aid uuid;nid uuid;answer jsonb;keys text[];
begin
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if keys is distinct from array['action','actionId','noticeId'] or p_input->>'action' is distinct from 'mark_read' then raise exception 'Invalid notice action' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;nid:=(p_input->>'noticeId')::uuid;if aid is null or nid is null then raise exception 'Invalid notice identity' using errcode='22023';end if;
 select * into n from public.pro_team_task_notices where id=nid;
 if not found or not public.pro_team_task_notice_allowed(p_actor,n) then raise exception 'Notice unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-team-task-notice:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||n.owner_id::text||':'||n.work_id,0));
 if n.recipient_grant_id is not null then perform 1 from public.pro_team_grants where id=n.recipient_grant_id for update;end if;
 select * into n from public.pro_team_task_notices where id=nid for update;
 if not public.pro_team_task_notice_allowed(p_actor,n) then raise exception 'Notice unavailable' using errcode='42501';end if;
 select * into r from public.pro_team_task_notice_actions where actor_id=p_actor and action_id=aid;
 if found then if r.input is distinct from p_input then raise exception 'Notice action reused' using errcode='22023';end if;return r.result;end if;
 if n.read_at is null then update public.pro_team_task_notices set read_at=now() where id=nid returning * into n;end if;
 answer:=jsonb_build_object('noticeId',n.id,'readAt',n.read_at);insert into public.pro_team_task_notice_actions(actor_id,action_id,notice_id,input,result) values(p_actor,aid,nid,p_input,answer);return answer;
end $$;
create or replace function public.pro_team_task_notice_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare n public.pro_team_task_notices;r public.pro_team_task_notice_actions;
begin
 select * into r from public.pro_team_task_notice_actions where actor_id=p_actor and action_id=p_action;if not found then return null;end if;
 select * into n from public.pro_team_task_notices where id=r.notice_id;
 if not found or not public.pro_team_task_notice_allowed(p_actor,n) then raise exception 'Notice unavailable' using errcode='42501';end if;return r.result;
end $$;
create or replace function public.pro_team_task_notice_immutable() returns trigger language plpgsql security invoker set search_path=public,pg_temp as $$
begin if (to_jsonb(new)-'read_at') is distinct from(to_jsonb(old)-'read_at') or old.read_at is not null or new.read_at is null then raise exception 'Notice content is immutable' using errcode='23514';end if;return new;end $$;
drop trigger if exists pro_team_task_mentions_immutable on public.pro_team_task_mentions;
create trigger pro_team_task_mentions_immutable before update on public.pro_team_task_mentions for each row execute function public.pro_team_append_only();
drop trigger if exists pro_team_task_mention_actions_immutable on public.pro_team_task_mention_actions;
create trigger pro_team_task_mention_actions_immutable before update on public.pro_team_task_mention_actions for each row execute function public.pro_team_append_only();
drop trigger if exists pro_team_task_notice_actions_immutable on public.pro_team_task_notice_actions;
create trigger pro_team_task_notice_actions_immutable before update on public.pro_team_task_notice_actions for each row execute function public.pro_team_append_only();
drop trigger if exists pro_team_task_notices_immutable on public.pro_team_task_notices;
create trigger pro_team_task_notices_immutable before update on public.pro_team_task_notices for each row execute function public.pro_team_task_notice_immutable();
alter table public.pro_team_task_mentions enable row level security;alter table public.pro_team_task_mention_actions enable row level security;alter table public.pro_team_task_notices enable row level security;alter table public.pro_team_task_notice_actions enable row level security;
revoke all on public.pro_team_task_mentions,public.pro_team_task_mention_actions,public.pro_team_task_notices,public.pro_team_task_notice_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_team_task_mentions,public.pro_team_task_mention_actions,public.pro_team_task_notices,public.pro_team_task_notice_actions to service_role;
revoke all on function public.pro_team_task_mention_targets(uuid,uuid,uuid,uuid),public.pro_team_task_comment_with_mentions(uuid,jsonb),public.pro_team_task_mention_comment_proof(uuid,uuid,uuid,uuid),public.pro_team_task_notice_allowed(uuid,public.pro_team_task_notices),public.pro_team_task_notice_json(public.pro_team_task_notices),public.pro_team_task_notice_inbox(uuid,text,uuid),public.pro_team_task_notice_open(uuid,uuid),public.pro_team_task_notice_mark_read(uuid,jsonb),public.pro_team_task_notice_action_read(uuid,uuid),public.pro_team_task_notice_immutable() from public,anon,authenticated;
grant execute on function public.pro_team_task_mention_targets(uuid,uuid,uuid,uuid),public.pro_team_task_comment_with_mentions(uuid,jsonb),public.pro_team_task_mention_comment_proof(uuid,uuid,uuid,uuid),public.pro_team_task_notice_allowed(uuid,public.pro_team_task_notices),public.pro_team_task_notice_json(public.pro_team_task_notices),public.pro_team_task_notice_inbox(uuid,text,uuid),public.pro_team_task_notice_open(uuid,uuid),public.pro_team_task_notice_mark_read(uuid,jsonb),public.pro_team_task_notice_action_read(uuid,uuid) to service_role;
commit;

-- ===== work-schedule-local.sql =====
-- LOCAL PRO ONLY. Manual planned periods and informative dependencies; no reminders or sends.
-- Does not alter existing task due dates, statuses, bookings or workspace JSON.
begin;
create table if not exists public.pro_work_schedule_heads(
 owner_id uuid not null,work_id text not null,revision integer not null check(revision>0),updated_at timestamptz not null default now(),primary key(owner_id,work_id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create table if not exists public.pro_work_schedule_phases(
 owner_id uuid not null,work_id text not null,id uuid not null,title text not null check(length(btrim(title)) between 1 and 160),position integer not null check(position between 0 and 999),archived boolean not null default false,
 primary key(owner_id,work_id,id),foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create table if not exists public.pro_work_schedule_plans(
 owner_id uuid not null,work_id text not null,task_id uuid not null,phase_id uuid,planned_start date,planned_end date,
 primary key(owner_id,work_id,task_id),foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade,
 foreign key(owner_id,work_id,phase_id) references public.pro_work_schedule_phases(owner_id,work_id,id),
 check((planned_start is null and planned_end is null) or(planned_start is not null and planned_end is not null and planned_start between date'1900-01-01' and date'2100-12-31' and planned_end between date'1900-01-01' and date'2100-12-31' and planned_start<=planned_end))
);
create table if not exists public.pro_work_schedule_dependencies(
 owner_id uuid not null,work_id text not null,task_id uuid not null,predecessor_id uuid not null,
 primary key(owner_id,work_id,task_id,predecessor_id),check(task_id<>predecessor_id),
 foreign key(owner_id,work_id,task_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade,
 foreign key(owner_id,work_id,predecessor_id) references public.pro_work_tasks(owner_id,work_id,id) on delete cascade
);
create index if not exists pro_work_schedule_dependencies_reverse on public.pro_work_schedule_dependencies(owner_id,work_id,predecessor_id,task_id);
create table if not exists public.pro_work_schedule_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,work_id text not null,input jsonb not null,result jsonb not null,before_state jsonb,at timestamptz not null default now(),
 primary key(actor_id,action_id),foreign key(actor_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create or replace function public.pro_work_schedule_owner(p_actor uuid,p_work text) returns void language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin if not coalesce(public.pro_appointment_enabled(p_actor),false) or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;end $$;
create or replace function public.pro_work_schedule_phase_json(p_phase public.pro_work_schedule_phases) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_phase.id,'title',p_phase.title,'position',p_phase.position,'archived',p_phase.archived);
$$;
create or replace function public.pro_work_schedule_plan_json(p_owner uuid,p_work text,p_task uuid) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('taskId',p_task,'phaseId',(select phase_id from public.pro_work_schedule_plans where owner_id=p_owner and work_id=p_work and task_id=p_task),
 'plannedStart',(select to_char(planned_start,'YYYY-MM-DD') from public.pro_work_schedule_plans where owner_id=p_owner and work_id=p_work and task_id=p_task),
 'plannedEnd',(select to_char(planned_end,'YYYY-MM-DD') from public.pro_work_schedule_plans where owner_id=p_owner and work_id=p_work and task_id=p_task),
 'dependsOn',coalesce((select jsonb_agg(predecessor_id order by predecessor_id) from public.pro_work_schedule_dependencies where owner_id=p_owner and work_id=p_work and task_id=p_task),'[]'::jsonb));
$$;
create or replace function public.pro_work_schedule_read(p_actor uuid,p_work text default null,p_grant uuid default null,p_after uuid default null,p_options boolean default false,p_query text default '') returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare own uuid;wid text;g public.pro_team_grants;items jsonb;phases jsonb;cursor_id uuid;rev integer;
begin
 if p_grant is not null then
  if p_work is not null then raise exception 'Ambiguous schedule scope' using errcode='22023';end if;
  g:=public.pro_team_context(p_actor,p_grant,false);own:=g.owner_id;wid:=g.work_id;
 else perform public.pro_work_schedule_owner(p_actor,p_work);own:=p_actor;wid:=p_work;end if;
 if p_query is null or length(p_query)>100 or not p_options and p_query<>'' then raise exception 'Invalid schedule query' using errcode='22023';end if;
 if p_after is not null and not exists(select 1 from public.pro_work_tasks where owner_id=own and work_id=wid and id=p_after and not archived and (p_query='' or position(lower(p_query) in lower(title))>0)) then raise exception 'Invalid schedule cursor' using errcode='22023';end if;
 if p_options then
  select coalesce(jsonb_agg(jsonb_build_object('id',t.id,'title',t.title) order by t.id),'[]'::jsonb) into items from(select id,title from public.pro_work_tasks where owner_id=own and work_id=wid and not archived and (p_after is null or id>p_after) and(p_query='' or position(lower(p_query) in lower(title))>0) order by id limit 21)t;
 else
  select coalesce(jsonb_agg(jsonb_build_object('task',jsonb_build_object('id',t.id,'title',t.title,'status',t.status,'dueDate',case when t.due_date is null then null else to_char(t.due_date,'YYYY-MM-DD') end,'revision',t.revision),'plan',public.pro_work_schedule_plan_json(own,wid,t.id),
  'dependencies',coalesce((select jsonb_agg(jsonb_build_object('taskId',d.predecessor_id,'title',case when not dt.archived then dt.title else null end,'status',case when not dt.archived then dt.status else null end,'available',coalesce(not dt.archived,false)) order by d.predecessor_id) from public.pro_work_schedule_dependencies d left join public.pro_work_tasks dt on dt.owner_id=d.owner_id and dt.work_id=d.work_id and dt.id=d.predecessor_id where d.owner_id=own and d.work_id=wid and d.task_id=t.id),'[]'::jsonb)) order by t.id),'[]'::jsonb) into items from(select * from public.pro_work_tasks where owner_id=own and work_id=wid and not archived and(p_after is null or id>p_after) order by id limit 21)t;
 end if;
 if jsonb_array_length(items)>20 then cursor_id:=case when p_options then (items->19->>'id')::uuid else (items->19->'task'->>'id')::uuid end;items:=items-20;end if;
 if p_options then return jsonb_build_object('items',items,'nextCursor',cursor_id);end if;
 select coalesce(jsonb_agg(public.pro_work_schedule_phase_json(p::public.pro_work_schedule_phases) order by p.position,p.id),'[]'::jsonb) into phases from(select * from public.pro_work_schedule_phases where owner_id=own and work_id=wid and not archived order by position,id limit 50)p;
 select revision into rev from public.pro_work_schedule_heads where owner_id=own and work_id=wid;
 return jsonb_build_object('workId',wid,'revision',coalesce(rev,0),'phases',phases,'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_work_schedule_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;wid text;pid uuid;tid uuid;rev integer;current_rev integer;keys text[];phase public.pro_work_schedule_phases;r public.pro_work_schedule_actions;start_date date;end_date date;dependencies uuid[];dep uuid;answer jsonb;before_json jsonb;title_text text;pos integer;
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid schedule operation' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if act='phase_save' then
  if keys is distinct from array['action','actionId','phaseId','position','revision','title','workId'] or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'position') is distinct from 'number' or not coalesce((p_input->>'position')~'^[0-9]{1,3}$',false) then raise exception 'Invalid phase fields' using errcode='22023';end if;
  title_text:=btrim(p_input->>'title');pos:=(p_input->>'position')::integer;if length(title_text) not between 1 and 160 or pos not between 0 and 999 then raise exception 'Invalid phase content' using errcode='22023';end if;
 elsif act='phase_archive' then
  if keys is distinct from array['action','actionId','phaseId','revision','workId'] then raise exception 'Invalid phase archive fields' using errcode='22023';end if;
 elsif act='task_plan' then
  if keys is distinct from array['action','actionId','dependsOn','phaseId','plannedEnd','plannedStart','revision','taskId','workId'] or jsonb_typeof(p_input->'dependsOn') is distinct from 'array' or jsonb_array_length(p_input->'dependsOn')>5 or jsonb_typeof(p_input->'phaseId') not in('null','string') or jsonb_typeof(p_input->'plannedStart') not in('null','string') or jsonb_typeof(p_input->'plannedEnd') not in('null','string') then raise exception 'Invalid task plan fields' using errcode='22023';end if;
  if (p_input->>'plannedStart' is null)<>(p_input->>'plannedEnd' is null) then raise exception 'Incomplete planned period' using errcode='22023';end if;
  if p_input->>'plannedStart' is not null then
   if not coalesce((p_input->>'plannedStart')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) or not coalesce((p_input->>'plannedEnd')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid planned date' using errcode='22023';end if;
   start_date:=(p_input->>'plannedStart')::date;end_date:=(p_input->>'plannedEnd')::date;
   if start_date not between date'1900-01-01' and date'2100-12-31' or end_date not between date'1900-01-01' and date'2100-12-31' or start_date>end_date then raise exception 'Invalid planned period' using errcode='22023';end if;
  end if;
  select coalesce(array_agg(value::uuid order by value::uuid),array[]::uuid[]) into dependencies from jsonb_array_elements_text(p_input->'dependsOn');
  if (select count(distinct v) from unnest(dependencies)v)<>cardinality(dependencies) or array_position(dependencies,null) is not null then raise exception 'Duplicate dependency' using errcode='22023';end if;
 elsif act='task_clear' then
  if keys is distinct from array['action','actionId','revision','taskId','workId'] then raise exception 'Invalid task clear fields' using errcode='22023';end if;
 else raise exception 'Unknown schedule operation' using errcode='22023';end if;
 if jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid schedule identity' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';rev:=(p_input->>'revision')::integer;
 if length(wid) not between 1 and 160 then raise exception 'Invalid schedule scope' using errcode='22023';end if;
 if act in('phase_save','phase_archive','task_plan') then pid:=(p_input->>'phaseId')::uuid;if act<>'task_plan' and pid is null then raise exception 'Missing phase identity' using errcode='22023';end if;end if;
 if act in('task_plan','task_clear') then tid:=(p_input->>'taskId')::uuid;if tid is null then raise exception 'Missing task identity' using errcode='22023';end if;end if;
 perform public.pro_work_schedule_owner(p_actor,wid);
 perform pg_advisory_xact_lock(hashtextextended('pro-work-schedule-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 perform public.pro_work_schedule_owner(p_actor,wid);
 select * into r from public.pro_work_schedule_actions where actor_id=p_actor and action_id=aid;
 if found then if r.input is distinct from p_input then raise exception 'Schedule identity reused' using errcode='22023';end if;return r.result;end if;
 select revision into current_rev from public.pro_work_schedule_heads where owner_id=p_actor and work_id=wid for update;current_rev:=coalesce(current_rev,0);
 if rev<>current_rev then raise exception 'Schedule changed' using errcode='40001';end if;
 if current_rev>=2147483647 then raise exception 'Schedule revision exhausted' using errcode='54000';end if;
 if act in('phase_save','phase_archive') then
  select * into phase from public.pro_work_schedule_phases where owner_id=p_actor and work_id=wid and id=pid for update;
  if found then
   before_json:=public.pro_work_schedule_phase_json(phase);
   if phase.archived then raise exception 'Phase archived' using errcode='22023';end if;
   update public.pro_work_schedule_phases set title=case when act='phase_save' then title_text else title end,position=case when act='phase_save' then pos else position end,archived=act='phase_archive' where owner_id=p_actor and work_id=wid and id=pid returning * into phase;
  else
   if act='phase_archive' then raise exception 'Phase unavailable' using errcode='22023';end if;
   if (select count(*) from public.pro_work_schedule_phases where owner_id=p_actor and work_id=wid and not archived)>=50 then raise exception 'Phase limit reached' using errcode='54000';end if;
   insert into public.pro_work_schedule_phases(owner_id,work_id,id,title,position) values(p_actor,wid,pid,title_text,pos) returning * into phase;
  end if;
  answer:=jsonb_build_object('action',act,'workId',wid,'revision',current_rev+1,'phase',public.pro_work_schedule_phase_json(phase));
 else
  perform 1 from public.pro_work_tasks where owner_id=p_actor and work_id=wid and id=tid and not archived for update;if not found then raise exception 'Task unavailable' using errcode='42501';end if;
  before_json:=public.pro_work_schedule_plan_json(p_actor,wid,tid);
  if act='task_clear' then
   delete from public.pro_work_schedule_dependencies where owner_id=p_actor and work_id=wid and task_id=tid;
   delete from public.pro_work_schedule_plans where owner_id=p_actor and work_id=wid and task_id=tid;
  else
   if pid is not null and not exists(select 1 from public.pro_work_schedule_phases where owner_id=p_actor and work_id=wid and id=pid and not archived) then raise exception 'Phase changed' using errcode='40001';end if;
   if tid=any(dependencies) then raise exception 'Task cannot depend on itself' using errcode='22023';end if;
   foreach dep in array dependencies loop
    perform 1 from public.pro_work_tasks where owner_id=p_actor and work_id=wid and id=dep and not archived for update;if not found then raise exception 'Dependency unavailable' using errcode='40001';end if;
   end loop;
   if not exists(select 1 from public.pro_work_schedule_plans where owner_id=p_actor and work_id=wid and task_id=tid) and(select count(*) from public.pro_work_schedule_plans where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Plan task limit reached' using errcode='54000';end if;
   insert into public.pro_work_schedule_plans(owner_id,work_id,task_id,phase_id,planned_start,planned_end) values(p_actor,wid,tid,pid,start_date,end_date) on conflict(owner_id,work_id,task_id) do update set phase_id=excluded.phase_id,planned_start=excluded.planned_start,planned_end=excluded.planned_end;
   delete from public.pro_work_schedule_dependencies where owner_id=p_actor and work_id=wid and task_id=tid;
   insert into public.pro_work_schedule_dependencies(owner_id,work_id,task_id,predecessor_id) select p_actor,wid,tid,v from unnest(dependencies)v;
   if exists(with recursive walk(id) as(select predecessor_id from public.pro_work_schedule_dependencies where owner_id=p_actor and work_id=wid and task_id=tid union select d.predecessor_id from public.pro_work_schedule_dependencies d join walk w on w.id=d.task_id where d.owner_id=p_actor and d.work_id=wid) select 1 from walk where id=tid) then raise exception 'Dependencies contain a cycle' using errcode='40001';end if;
  end if;
  answer:=jsonb_build_object('action',act,'workId',wid,'revision',current_rev+1,'plan',public.pro_work_schedule_plan_json(p_actor,wid,tid));
 end if;
 perform public.pro_work_schedule_owner(p_actor,wid);
 insert into public.pro_work_schedule_heads(owner_id,work_id,revision) values(p_actor,wid,current_rev+1) on conflict(owner_id,work_id) do update set revision=excluded.revision,updated_at=now();
 insert into public.pro_work_schedule_actions(actor_id,action_id,work_id,input,result,before_state) values(p_actor,aid,wid,p_input,answer,before_json);return answer;
end $$;
create or replace function public.pro_work_schedule_action_read(p_actor uuid,p_work text,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_work_schedule_actions;phase public.pro_work_schedule_phases;act text;rev integer;tid uuid;
begin
 perform public.pro_work_schedule_owner(p_actor,p_work);
 select * into r from public.pro_work_schedule_actions where actor_id=p_actor and work_id=p_work and action_id=p_action;if not found then return null;end if;
 select revision into rev from public.pro_work_schedule_heads where owner_id=p_actor and work_id=p_work;act:=r.input->>'action';
 if act in('phase_save','phase_archive') then
  select * into phase from public.pro_work_schedule_phases where owner_id=p_actor and work_id=p_work and id=(r.input->>'phaseId')::uuid;if not found then return null;end if;
  return r.result;
 end if;
 tid:=(r.input->>'taskId')::uuid;
 if not exists(select 1 from public.pro_work_tasks where owner_id=p_actor and work_id=p_work and id=tid and not archived) then raise exception 'Task unavailable' using errcode='42501';end if;
 return r.result;
end $$;
drop trigger if exists pro_work_schedule_actions_immutable on public.pro_work_schedule_actions;
create trigger pro_work_schedule_actions_immutable before update on public.pro_work_schedule_actions for each row execute function public.pro_team_append_only();
alter table public.pro_work_schedule_heads enable row level security;alter table public.pro_work_schedule_phases enable row level security;alter table public.pro_work_schedule_plans enable row level security;alter table public.pro_work_schedule_dependencies enable row level security;alter table public.pro_work_schedule_actions enable row level security;
revoke all on public.pro_work_schedule_heads,public.pro_work_schedule_phases,public.pro_work_schedule_plans,public.pro_work_schedule_dependencies,public.pro_work_schedule_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_schedule_heads,public.pro_work_schedule_phases,public.pro_work_schedule_plans,public.pro_work_schedule_dependencies,public.pro_work_schedule_actions to service_role;
revoke all on function public.pro_work_schedule_owner(uuid,text),public.pro_work_schedule_phase_json(public.pro_work_schedule_phases),public.pro_work_schedule_plan_json(uuid,text,uuid),public.pro_work_schedule_read(uuid,text,uuid,uuid,boolean,text),public.pro_work_schedule_mutate(uuid,jsonb),public.pro_work_schedule_action_read(uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.pro_work_schedule_owner(uuid,text),public.pro_work_schedule_phase_json(public.pro_work_schedule_phases),public.pro_work_schedule_plan_json(uuid,text,uuid),public.pro_work_schedule_read(uuid,text,uuid,uuid,boolean,text),public.pro_work_schedule_mutate(uuid,jsonb),public.pro_work_schedule_action_read(uuid,text,uuid) to service_role;
commit;

-- ===== work-schedule-milestones-local.sql =====
-- LOCAL PRO ONLY. Named civil dates, independent from tasks and appointment dates.
-- Add after work-schedule-local.sql. Existing writers and receipts remain unchanged.
begin;
create table if not exists public.pro_work_schedule_milestones(
 owner_id uuid not null,work_id text not null,id uuid not null,
 title text not null check(length(btrim(title)) between 1 and 160),
 milestone_date date not null check(milestone_date between date '1900-01-01' and date '2100-12-31'),
 notes text not null default '' check(length(notes)<=1000),archived boolean not null default false,
 primary key(owner_id,work_id,id),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_schedule_milestones_page on public.pro_work_schedule_milestones(owner_id,work_id,archived,milestone_date,id);
create or replace function public.pro_work_milestone_json(p_item public.pro_work_schedule_milestones) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_item.id,'title',p_item.title,'date',to_char(p_item.milestone_date,'YYYY-MM-DD'),'notes',p_item.notes,'archived',p_item.archived);
$$;
create or replace function public.pro_work_milestones_read(p_actor uuid,p_work text default null,p_grant uuid default null,p_status text default 'active',p_after uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare own uuid;wid text;g public.pro_team_grants;items jsonb;cursor_date date;cursor_id uuid;rev integer;want_archived boolean;
begin
 if p_status is null or p_status not in('active','archived') then raise exception 'Invalid milestone status' using errcode='22023';end if;
 if p_grant is not null then
  if p_work is not null then raise exception 'Ambiguous milestone scope' using errcode='22023';end if;
  g:=public.pro_team_context(p_actor,p_grant,false);own:=g.owner_id;wid:=g.work_id;
  if p_status<>'active' then raise exception 'Forbidden' using errcode='42501';end if;
 else perform public.pro_work_schedule_owner(p_actor,p_work);own:=p_actor;wid:=p_work;end if;
 want_archived:=p_status='archived';
 if p_after is not null then
  select milestone_date into cursor_date from public.pro_work_schedule_milestones where owner_id=own and work_id=wid and id=p_after and archived=want_archived;
  if not found then raise exception 'Invalid milestone cursor' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(public.pro_work_milestone_json(m::public.pro_work_schedule_milestones) order by m.milestone_date,m.id),'[]'::jsonb) into items from(
  select * from public.pro_work_schedule_milestones where owner_id=own and work_id=wid and archived=want_archived and(p_after is null or(milestone_date,id)>(cursor_date,p_after)) order by milestone_date,id limit 21
 )m;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;
 select revision into rev from public.pro_work_schedule_heads where owner_id=own and work_id=wid;
 return jsonb_build_object('workId',wid,'revision',coalesce(rev,0),'items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_work_milestones_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;wid text;mid uuid;rev integer;current_rev integer;keys text[];r public.pro_work_schedule_actions;m public.pro_work_schedule_milestones;title_text text;note_text text;day date;before_json jsonb;answer jsonb;
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid milestone operation' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if act='milestone_save' then
  if keys is distinct from array['action','actionId','date','milestoneId','notes','revision','title','workId'] or jsonb_typeof(p_input->'title') is distinct from 'string' or jsonb_typeof(p_input->'notes') is distinct from 'string' or jsonb_typeof(p_input->'date') is distinct from 'string' then raise exception 'Invalid milestone fields' using errcode='22023';end if;
  title_text:=btrim(p_input->>'title');note_text:=btrim(p_input->>'notes');
  if length(title_text) not between 1 and 160 or length(note_text)>1000 or not coalesce((p_input->>'date')~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$',false) then raise exception 'Invalid milestone content' using errcode='22023';end if;
  day:=(p_input->>'date')::date;if day not between date '1900-01-01' and date '2100-12-31' then raise exception 'Invalid milestone date' using errcode='22023';end if;
 elsif act in('milestone_archive','milestone_restore') then
  if keys is distinct from array['action','actionId','milestoneId','revision','workId'] then raise exception 'Invalid milestone archive fields' using errcode='22023';end if;
 else raise exception 'Unknown milestone operation' using errcode='22023';end if;
 if jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'milestoneId') is distinct from 'string' or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483646 then raise exception 'Invalid milestone identity' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;mid:=(p_input->>'milestoneId')::uuid;wid:=p_input->>'workId';rev:=(p_input->>'revision')::integer;
 if length(wid) not between 1 and 160 then raise exception 'Invalid milestone scope' using errcode='22023';end if;
 perform public.pro_work_schedule_owner(p_actor,wid);
 perform pg_advisory_xact_lock(hashtextextended('pro-work-schedule-action:'||p_actor::text||':'||aid::text,0));
 perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||wid,0));
 perform public.pro_work_schedule_owner(p_actor,wid);
 select * into r from public.pro_work_schedule_actions where actor_id=p_actor and action_id=aid;
 if found then if r.input is distinct from p_input then raise exception 'Schedule identity reused' using errcode='22023';end if;return r.result;end if;
 select revision into current_rev from public.pro_work_schedule_heads where owner_id=p_actor and work_id=wid for update;current_rev:=coalesce(current_rev,0);
 if rev<>current_rev then raise exception 'Schedule changed' using errcode='40001';end if;
 if current_rev>=2147483647 then raise exception 'Schedule revision exhausted' using errcode='54000';end if;
 select * into m from public.pro_work_schedule_milestones where owner_id=p_actor and work_id=wid and id=mid for update;
 if found then
  before_json:=public.pro_work_milestone_json(m);
  if act='milestone_save' then
   if m.archived then raise exception 'Milestone archived' using errcode='40001';end if;
   update public.pro_work_schedule_milestones set title=title_text,milestone_date=day,notes=note_text where owner_id=p_actor and work_id=wid and id=mid returning * into m;
  else
   if m.archived=(act='milestone_archive') then raise exception 'Milestone status changed' using errcode='40001';end if;
   update public.pro_work_schedule_milestones set archived=act='milestone_archive' where owner_id=p_actor and work_id=wid and id=mid returning * into m;
  end if;
 else
  if act<>'milestone_save' then raise exception 'Milestone unavailable' using errcode='42501';end if;
  if(select count(*) from public.pro_work_schedule_milestones where owner_id=p_actor and work_id=wid)>=500 then raise exception 'Milestone limit reached' using errcode='54000';end if;
  insert into public.pro_work_schedule_milestones(owner_id,work_id,id,title,milestone_date,notes) values(p_actor,wid,mid,title_text,day,note_text) returning * into m;
 end if;
 perform public.pro_work_schedule_owner(p_actor,wid);
 answer:=jsonb_build_object('action',act,'workId',wid,'revision',current_rev+1,'milestone',public.pro_work_milestone_json(m));
 insert into public.pro_work_schedule_heads(owner_id,work_id,revision) values(p_actor,wid,current_rev+1) on conflict(owner_id,work_id) do update set revision=excluded.revision,updated_at=now();
 insert into public.pro_work_schedule_actions(actor_id,action_id,work_id,input,result,before_state) values(p_actor,aid,wid,p_input,answer,before_json);return answer;
end $$;
create or replace function public.pro_work_schedule_action_v2_read(p_actor uuid,p_work text,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_work_schedule_actions;
begin
 perform public.pro_work_schedule_owner(p_actor,p_work);
 select * into r from public.pro_work_schedule_actions where actor_id=p_actor and work_id=p_work and action_id=p_action;
 if not found then return null;end if;
 if r.input->>'action' not in('milestone_save','milestone_archive','milestone_restore') then return public.pro_work_schedule_action_read(p_actor,p_work,p_action);end if;
 if not exists(select 1 from public.pro_work_schedule_milestones where owner_id=p_actor and work_id=p_work and id=(r.input->>'milestoneId')::uuid) then raise exception 'Milestone unavailable' using errcode='42501';end if;
 return r.result;
end $$;
alter table public.pro_work_schedule_milestones enable row level security;
revoke all on public.pro_work_schedule_milestones from public,anon,authenticated;
grant select,insert,update,delete on public.pro_work_schedule_milestones to service_role;
revoke all on function public.pro_work_milestone_json(public.pro_work_schedule_milestones),public.pro_work_milestones_read(uuid,text,uuid,text,uuid),public.pro_work_milestones_mutate(uuid,jsonb),public.pro_work_schedule_action_v2_read(uuid,text,uuid) from public,anon,authenticated;
grant execute on function public.pro_work_milestone_json(public.pro_work_schedule_milestones),public.pro_work_milestones_read(uuid,text,uuid,text,uuid),public.pro_work_milestones_mutate(uuid,jsonb),public.pro_work_schedule_action_v2_read(uuid,text,uuid) to service_role;
commit;

-- ===== work-schedule-timeline-local.sql =====
-- LOCAL PRO ONLY. Bounded civil timeline, read-only normalized tasks/plans/milestones.
-- No existing function changes, data backfill, workspace reads or scheduling writes.
begin;
create or replace function public.pro_work_timeline_item_json(p_task public.pro_work_tasks) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('task',jsonb_build_object('id',p_task.id,'title',p_task.title,'status',p_task.status,'dueDate',case when p_task.due_date is null then null else to_char(p_task.due_date,'YYYY-MM-DD') end,'revision',p_task.revision),
 'plan',public.pro_work_schedule_plan_json(p_task.owner_id,p_task.work_id,p_task.id),
 'dependencies',coalesce((select jsonb_agg(jsonb_build_object('taskId',d.predecessor_id,'title',case when not dt.archived then dt.title else null end,'status',case when not dt.archived then dt.status else null end,'available',coalesce(not dt.archived,false)) order by d.predecessor_id)
 from public.pro_work_schedule_dependencies d left join public.pro_work_tasks dt on dt.owner_id=d.owner_id and dt.work_id=d.work_id and dt.id=d.predecessor_id where d.owner_id=p_task.owner_id and d.work_id=p_task.work_id and d.task_id=p_task.id),'[]'::jsonb));
$$;
create or replace function public.pro_work_timeline_read(p_actor uuid,p_work text default null,p_grant uuid default null,p_from text default null,p_to text default null,p_after text default null,p_revision integer default null,p_snapshot text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare own uuid;wid text;g public.pro_team_grants;first_day date;last_day date;rev integer;items jsonb;phases jsonb;cursor_id uuid;cursor_kind integer;cursor_day date;next_cursor text;planned_count bigint;milestone_count bigint;unscheduled_count bigint;snapshot_token text;
begin
 if p_grant is not null then
  if p_work is not null then raise exception 'Ambiguous timeline scope' using errcode='22023';end if;
  g:=public.pro_team_context(p_actor,p_grant,false);own:=g.owner_id;wid:=g.work_id;
 else perform public.pro_work_schedule_owner(p_actor,p_work);own:=p_actor;wid:=p_work;end if;
 if p_from is null or p_to is null or not p_from~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or not p_to~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid timeline dates' using errcode='22023';end if;
 first_day:=p_from::date;last_day:=p_to::date;
 if first_day not between date'1900-01-01' and date'2100-12-31' or last_day not between date'1900-01-01' and date'2100-12-31' or last_day-first_day not between 0 and 92 then raise exception 'Invalid timeline window' using errcode='22023';end if;
 select revision into rev from public.pro_work_schedule_heads where owner_id=own and work_id=wid;rev:=coalesce(rev,0);
 -- Hash only identity/revision/archive state, never private task content. All tasks
 -- also cover unscheduled totals and new/archived tasks between pages.
 select md5(own::text||':'||length(wid)::text||':'||wid||':'||p_from||':'||p_to||':'||rev::text||':'||coalesce(string_agg(t.id::text||':'||t.revision::text||':'||t.archived::text,',' order by t.id),'')) into snapshot_token from public.pro_work_tasks t where t.owner_id=own and t.work_id=wid;
 if p_snapshot is not null and not p_snapshot~'^[a-f0-9]{32}$' or p_after is not null and p_snapshot is null then raise exception 'Missing timeline snapshot' using errcode='22023';end if;
 if p_snapshot is not null and p_snapshot<>snapshot_token then raise exception 'Timeline tasks changed' using errcode='40001';end if;
 if p_revision is not null and p_revision<0 or p_after is not null and p_revision is null then raise exception 'Missing timeline revision' using errcode='22023';end if;
 if p_revision is not null and p_revision<>rev then raise exception 'Timeline changed' using errcode='40001';end if;
 if p_after is not null then
  if length(p_after)>48 or not p_after~'^(task|milestone):[a-fA-F0-9-]{36}$' then raise exception 'Invalid timeline cursor' using errcode='22023';end if;
  cursor_id:=split_part(p_after,':',2)::uuid;
  if split_part(p_after,':',1)='task' then
   cursor_kind:=0;
   select p.planned_start into cursor_day from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
   where p.owner_id=own and p.work_id=wid and p.task_id=cursor_id and not t.archived and p.planned_start<=last_day and p.planned_end>=first_day;
  else
   cursor_kind:=1;
   select milestone_date into cursor_day from public.pro_work_schedule_milestones where owner_id=own and work_id=wid and id=cursor_id and not archived and milestone_date between first_day and last_day;
  end if;
  if not found then raise exception 'Timeline cursor changed; reload' using errcode='40001';end if;
 end if;
 select count(*) into planned_count from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id where p.owner_id=own and p.work_id=wid and not t.archived and p.planned_start<=last_day and p.planned_end>=first_day;
 select count(*) into milestone_count from public.pro_work_schedule_milestones where owner_id=own and work_id=wid and not archived and milestone_date between first_day and last_day;
 select count(*) into unscheduled_count from public.pro_work_tasks t left join public.pro_work_schedule_plans p on p.owner_id=t.owner_id and p.work_id=t.work_id and p.task_id=t.id where t.owner_id=own and t.work_id=wid and not t.archived and p.planned_start is null;
 select coalesce(jsonb_agg(entry order by source_day,kind,id),'[]'::jsonb) into items from(
  select * from(
   select p.planned_start source_day,0 kind,t.id,jsonb_build_object('kind','task','id',t.id,'item',public.pro_work_timeline_item_json(t),
    'visibleStart',to_char(greatest(p.planned_start,first_day),'YYYY-MM-DD'),'visibleEnd',to_char(least(p.planned_end,last_day),'YYYY-MM-DD'),'clippedStart',p.planned_start<first_day,'clippedEnd',p.planned_end>last_day) entry
   from public.pro_work_schedule_plans p join public.pro_work_tasks t on t.owner_id=p.owner_id and t.work_id=p.work_id and t.id=p.task_id
   where p.owner_id=own and p.work_id=wid and not t.archived and p.planned_start<=last_day and p.planned_end>=first_day
   union all
   select m.milestone_date,1,m.id,jsonb_build_object('kind','milestone','id',m.id,'milestone',public.pro_work_milestone_json(m),
    'visibleStart',to_char(m.milestone_date,'YYYY-MM-DD'),'visibleEnd',to_char(m.milestone_date,'YYYY-MM-DD'),'clippedStart',false,'clippedEnd',false)
   from public.pro_work_schedule_milestones m where m.owner_id=own and m.work_id=wid and not m.archived and m.milestone_date between first_day and last_day
  ) entries where p_after is null or(source_day,kind,id)>(cursor_day,cursor_kind,cursor_id) order by source_day,kind,id limit 21
 ) limited;
 if jsonb_array_length(items)>20 then next_cursor:=(items->19->>'kind')||':'||(items->19->>'id');items:=items-20;end if;
 select coalesce(jsonb_agg(public.pro_work_schedule_phase_json(p::public.pro_work_schedule_phases) order by p.position,p.id),'[]'::jsonb) into phases from(select * from public.pro_work_schedule_phases where owner_id=own and work_id=wid and not archived order by position,id limit 50)p;
 return jsonb_build_object('workId',wid,'revision',rev,'snapshotToken',snapshot_token,'window',jsonb_build_object('from',p_from,'to',p_to,'days',last_day-first_day+1),'phases',phases,'items',items,'nextCursor',next_cursor,'counts',jsonb_build_object('plannedTasks',planned_count,'milestones',milestone_count,'unscheduledTasks',unscheduled_count));
end $$;
revoke all on function public.pro_work_timeline_item_json(public.pro_work_tasks),public.pro_work_timeline_read(uuid,text,uuid,text,text,text,integer,text) from public,anon,authenticated;
grant execute on function public.pro_work_timeline_item_json(public.pro_work_tasks),public.pro_work_timeline_read(uuid,text,uuid,text,text,text,integer,text) to service_role;
commit;

-- ===== task-center-planning-local.sql =====
-- LOCAL PRO ONLY. Owner read-only planning metadata alongside unchanged legacy task rows.
-- No workspace JSON, mutations, private collaboration grants or existing RPC replacements.
begin;
create or replace function public.pro_task_center_planning_matches(p_task public.pro_work_tasks,p_work public.pro_work,p_needle text) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$
 select p_needle='' or position(p_needle in lower(p_task.title))>0 or position(p_needle in lower(p_task.details))>0 or position(p_needle in lower(p_task.assignee))>0 or position(p_needle in lower(p_work.service))>0 or position(p_needle in lower(p_work.client))>0
 or coalesce((select (a.assignment->>'active')::boolean and position(p_needle in lower(a.assignment->>'name'))>0 from(select public.pro_team_assignment_json(p_task.owner_id,p_task.id) assignment)a),false)
 or exists(select 1 from public.pro_work_schedule_plans p join public.pro_work_schedule_phases phase on phase.owner_id=p.owner_id and phase.work_id=p.work_id and phase.id=p.phase_id where p.owner_id=p_task.owner_id and p.work_id=p_task.work_id and p.task_id=p_task.id and not phase.archived and position(p_needle in lower(phase.title))>0);
$$;
create or replace function public.pro_task_center_planning_context(p_task public.pro_work_tasks) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('taskId',p_task.id,'assignment',public.pro_team_assignment_json(p_task.owner_id,p_task.id),
 'plan',(select jsonb_build_object('phaseId',p.phase_id,'phaseName',phase.title,'phaseArchived',coalesce(phase.archived,false),'plannedStart',to_char(p.planned_start,'YYYY-MM-DD'),'plannedEnd',to_char(p.planned_end,'YYYY-MM-DD'))
 from public.pro_work_schedule_plans p left join public.pro_work_schedule_phases phase on phase.owner_id=p.owner_id and phase.work_id=p.work_id and phase.id=p.phase_id where p.owner_id=p_task.owner_id and p.work_id=p_task.work_id and p.task_id=p_task.id));
$$;
create or replace function public.pro_task_center_planning_read(p_actor uuid,p_status text default 'open',p_timing text default 'all',p_query text default '',p_after uuid default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare today_cr date:=(now() at time zone 'America/Costa_Rica')::date;needle text;cursor_due date;cursor_id uuid;items jsonb;open_count integer;done_count integer;overdue_count integer;metadata jsonb;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_status is null or p_status not in('open','done','all') or p_timing is null or p_timing not in('all','overdue','today','upcoming') or p_query is null or length(p_query)>100 then raise exception 'Invalid task-center query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));
 -- Literal substring matching: percent/underscore never become SQL wildcards.
 select count(*) filter(where t.status='open'),count(*) filter(where t.status='done'),count(*) filter(where t.status='open' and t.due_date<today_cr)
 into open_count,done_count,overdue_count from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
 where t.owner_id=p_actor and not t.archived and public.pro_task_center_planning_matches(t,w,needle);
 if p_after is not null then
  select coalesce(t.due_date,date '9999-12-31') into cursor_due from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and t.id=p_after and not t.archived and (p_status='all' or t.status=p_status)
  and public.pro_task_center_planning_matches(t,w,needle)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end;
  if not found then raise exception 'Task-center cursor changed; refresh the list' using errcode='22023';end if;
 end if;
 select coalesce(jsonb_agg(jsonb_build_object('task',public.pro_work_task_json(x.task),'work',jsonb_build_object('id',x.work_id,'service',x.service,'client',x.client,'stage',x.stage,'cancelled',x.cancelled)) order by (x.task).due_date asc nulls last,(x.task).id),'[]'::jsonb) into items from (
  select t as task,w.id as work_id,w.service,w.client,w.stage,coalesce(w.cancelled,false) as cancelled
  from public.pro_work_tasks t join public.pro_work w on w.user_id=t.owner_id and w.id=t.work_id
  where t.owner_id=p_actor and not t.archived and (p_status='all' or t.status=p_status)
  and public.pro_task_center_planning_matches(t,w,needle)
  and case p_timing when 'all' then true when 'overdue' then t.status='open' and t.due_date<today_cr when 'today' then t.due_date=today_cr else t.due_date>today_cr end
  and (p_after is null or (coalesce(t.due_date,date '9999-12-31'),t.id)>(cursor_due,p_after))
  order by t.due_date asc nulls last,t.id limit 21
 ) x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->'task'->>'id')::uuid;items:=items-20;end if;
 -- Resolve metadata from this exact bounded page inside the same SQL snapshot.
 select coalesce(jsonb_agg(public.pro_task_center_planning_context(t) order by i.ordinality),'[]'::jsonb) into metadata
 from jsonb_array_elements(items) with ordinality i(entry,ordinality)
 join public.pro_work_tasks t on t.owner_id=p_actor and t.id=(i.entry->'task'->>'id')::uuid and t.work_id=(i.entry->'task'->>'workId');
 return jsonb_build_object('page',jsonb_build_object('items',items,'nextCursor',cursor_id,'counts',jsonb_build_object('open',open_count,'done',done_count,'overdue',overdue_count)),'context',metadata);
end $$;
revoke all on function public.pro_task_center_planning_matches(public.pro_work_tasks,public.pro_work,text),public.pro_task_center_planning_context(public.pro_work_tasks),public.pro_task_center_planning_read(uuid,text,text,text,uuid) from public,anon,authenticated;
grant execute on function public.pro_task_center_planning_matches(public.pro_work_tasks,public.pro_work,text),public.pro_task_center_planning_context(public.pro_work_tasks),public.pro_task_center_planning_read(uuid,text,text,text,uuid) to service_role;
commit;

-- ===== task-templates-local.sql =====
-- LOCAL PRO ONLY. Reusable task definitions, NOT priced service packages.
-- No real assignee/grant, attachment, comment, schedule or notification copying.
begin;
create table if not exists public.pro_task_templates(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 name text not null check(length(btrim(name)) between 1 and 80),notes text not null default '' check(length(notes)<=1000),
 revision integer not null default 1 check(revision>0),archived boolean not null default false,
 primary key(owner_id,id)
);
create index if not exists pro_task_templates_page on public.pro_task_templates(owner_id,archived,id);
create table if not exists public.pro_task_template_rows(
 owner_id uuid not null,template_id uuid not null,id uuid not null,position integer not null check(position between 0 and 99),
 title text not null check(length(btrim(title)) between 1 and 160),details text not null default '' check(length(details)<=2000),assignee text not null default '' check(length(assignee)<=160),due_offset integer check(due_offset between -80000 and 80000),
 primary key(owner_id,template_id,id),unique(owner_id,template_id,position),foreign key(owner_id,template_id) references public.pro_task_templates(owner_id,id) on delete cascade
);
create table if not exists public.pro_task_template_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,template_id uuid not null,
 input jsonb not null,result jsonb not null,before_state jsonb,after_state jsonb,at timestamptz not null default now(),primary key(actor_id,action_id),
 foreign key(actor_id,template_id) references public.pro_task_templates(owner_id,id) on delete cascade
);
alter table public.pro_task_template_actions add column if not exists after_state jsonb;
create or replace function public.pro_task_template_summary(p_template public.pro_task_templates) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_template.id,'name',p_template.name,'notes',p_template.notes,'revision',p_template.revision,'archived',p_template.archived,'count',(select count(*) from public.pro_task_template_rows where owner_id=p_template.owner_id and template_id=p_template.id));
$$;
create or replace function public.pro_task_template_detail(p_template public.pro_task_templates) returns jsonb language sql stable security invoker set search_path=public,pg_temp as $$
 select public.pro_task_template_summary(p_template)||jsonb_build_object('rows',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'title',r.title,'details',r.details,'assignee',r.assignee,'dueOffset',r.due_offset) order by r.position) from public.pro_task_template_rows r where r.owner_id=p_template.owner_id and r.template_id=p_template.id),'[]'::jsonb));
$$;
create or replace function public.pro_task_templates_read(p_actor uuid,p_status text default 'active',p_query text default '',p_after uuid default null,p_template uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare t public.pro_task_templates;items jsonb;cursor_id uuid;needle text;want_archived boolean;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_template is not null then
  if p_after is not null then raise exception 'Invalid template detail query' using errcode='22023';end if;
  select * into t from public.pro_task_templates where owner_id=p_actor and id=p_template;if not found then return null;end if;
  return jsonb_build_object('template',public.pro_task_template_detail(t));
 end if;
 if p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 then raise exception 'Invalid template list query' using errcode='22023';end if;
 needle:=lower(btrim(p_query));want_archived:=p_status='archived';
 if p_after is not null and not exists(select 1 from public.pro_task_templates where owner_id=p_actor and id=p_after and archived=want_archived and(needle='' or position(needle in lower(name))>0 or position(needle in lower(notes))>0)) then raise exception 'Template cursor changed' using errcode='22023';end if;
 select coalesce(jsonb_agg(public.pro_task_template_summary(x::public.pro_task_templates) order by x.id),'[]'::jsonb) into items from(select * from public.pro_task_templates where owner_id=p_actor and archived=want_archived and(needle='' or position(needle in lower(name))>0 or position(needle in lower(notes))>0) and(p_after is null or id>p_after) order by id limit 21)x;
 if jsonb_array_length(items)>20 then cursor_id:=(items->19->>'id')::uuid;items:=items-20;end if;return jsonb_build_object('items',items,'nextCursor',cursor_id);
end $$;
create or replace function public.pro_task_template_preview(p_actor uuid,p_template uuid,p_work text,p_start text default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare t public.pro_task_templates;r public.pro_task_template_rows;start_day date;due date;items jsonb:='[]'::jsonb;existing integer;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 or not exists(select 1 from public.pro_work where user_id=p_actor and id=p_work) then raise exception 'Forbidden' using errcode='42501';end if;
 if exists(select 1 from public.pro_work where user_id=p_actor and id=p_work and coalesce(cancelled,false)) then raise exception 'Target work cancelled' using errcode='40001';end if;
 select * into t from public.pro_task_templates where owner_id=p_actor and id=p_template;if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if t.archived then raise exception 'Template archived' using errcode='40001';end if;
 if p_start is not null then
  if not p_start~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid start date' using errcode='22023';end if;start_day:=p_start::date;
  if start_day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Invalid start date' using errcode='22023';end if;
 end if;
 select count(*) into existing from public.pro_work_tasks where owner_id=p_actor and work_id=p_work;
 if existing+(select count(*) from public.pro_task_template_rows where owner_id=p_actor and template_id=p_template)>500 then raise exception 'Target task capacity changed' using errcode='40001';end if;
 for r in select * from public.pro_task_template_rows where owner_id=p_actor and template_id=p_template order by position loop
  due:=null;
  if r.due_offset is not null then
   if start_day is null then raise exception 'Start date required' using errcode='22023';end if;due:=start_day+r.due_offset;
   if due not between date'1900-01-01' and date'2100-12-31' then raise exception 'Resulting task date outside range' using errcode='22023';end if;
  end if;
  items:=items||jsonb_build_array(jsonb_build_object('id',r.id,'title',r.title,'details',r.details,'assignee',r.assignee,'dueDate',case when due is null then null else to_char(due,'YYYY-MM-DD') end));
 end loop;
 if jsonb_array_length(items) not between 1 and 100 then raise exception 'Template rows unavailable' using errcode='22023';end if;
 return jsonb_build_object('template',public.pro_task_template_summary(t),'workId',p_work,'startDate',p_start,'existingCount',existing,'rows',items);
end $$;
create or replace function public.pro_task_templates_mutate(p_actor uuid,p_input jsonb) returns jsonb language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;template_key uuid;rev integer;keys text[];t public.pro_task_templates;receipt public.pro_task_template_actions;r jsonb;ref jsonb;task public.pro_work_tasks;work public.pro_work;
 name_text text;note_text text;rows_json jsonb;before_json jsonb;answer jsonb;preview jsonb;child_input jsonb;work_key text;source_work text;source_day date;offset_days integer;position_index integer;child_ids uuid[];new_ids uuid[];child_id uuid;seen uuid[]:=array[]::uuid[];
 include_details boolean;include_manual boolean;include_dates boolean;row_id uuid;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid task template' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(key order by key) into keys from jsonb_object_keys(p_input)key;
 if act='save' then
  if keys is distinct from array['action','actionId','name','notes','revision','rows','templateId'] or jsonb_typeof(p_input->'rows') is distinct from 'array' or jsonb_array_length(p_input->'rows') not between 1 and 100 then raise exception 'Invalid template definition' using errcode='22023';end if;
 elsif act='capture' then
  if not keys @> array['action','actionId','name','notes','revision','selected','templateId'] or not keys <@ array['action','actionId','includeDetails','includeDueDates','includeManual','name','notes','revision','selected','templateId'] or jsonb_typeof(p_input->'selected') is distinct from 'array' or jsonb_array_length(p_input->'selected') not between 1 and 100 then raise exception 'Invalid template capture' using errcode='22023';end if;
  foreach source_work in array array['includeDetails','includeManual','includeDueDates'] loop if p_input ? source_work and jsonb_typeof(p_input->source_work) is distinct from 'boolean' then raise exception 'Invalid copy option' using errcode='22023';end if;end loop;
  include_details:=coalesce((p_input->>'includeDetails')::boolean,false);include_manual:=coalesce((p_input->>'includeManual')::boolean,false);include_dates:=coalesce((p_input->>'includeDueDates')::boolean,true);
 elsif act in('archive','restore') then
  if keys is distinct from array['action','actionId','revision','templateId'] then raise exception 'Invalid template status action' using errcode='22023';end if;
 elsif act='apply' then
  if keys is distinct from array['action','actionId','newTaskIds','revision','startDate','taskActionIds','templateId','workId'] or jsonb_typeof(p_input->'workId') is distinct from 'string' or jsonb_typeof(p_input->'newTaskIds') is distinct from 'array' or jsonb_typeof(p_input->'taskActionIds') is distinct from 'array' or jsonb_typeof(p_input->'startDate') not in('null','string') then raise exception 'Invalid template application' using errcode='22023';end if;
  work_key:=p_input->>'workId';if length(work_key) not between 1 and 160 or jsonb_array_length(p_input->'newTaskIds') not between 1 and 100 or jsonb_array_length(p_input->'taskActionIds')<>jsonb_array_length(p_input->'newTaskIds') then raise exception 'Invalid task identities' using errcode='22023';end if;
  select array_agg(value::uuid order by ordinality) into new_ids from jsonb_array_elements_text(p_input->'newTaskIds')with ordinality;
  select array_agg(value::uuid order by ordinality) into child_ids from jsonb_array_elements_text(p_input->'taskActionIds')with ordinality;
  if (select count(distinct v) from unnest(new_ids)v)<>cardinality(new_ids) or(select count(distinct v) from unnest(child_ids)v)<>cardinality(child_ids) or array_position(new_ids,null) is not null or array_position(child_ids,null) is not null then raise exception 'Repeated task identities' using errcode='22023';end if;
 else raise exception 'Invalid template operation' using errcode='22023';end if;
 if jsonb_typeof(p_input->'actionId') is distinct from 'string' or jsonb_typeof(p_input->'templateId') is distinct from 'string' or jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or(p_input->>'revision')::numeric not between 0 and 2147483647 then raise exception 'Invalid template identity' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;template_key:=(p_input->>'templateId')::uuid;rev:=(p_input->>'revision')::integer;
 if act<>'apply' and rev>=2147483647 or act='capture' and rev<>0 or act in('archive','restore','apply') and rev=0 then raise exception 'Invalid template revision' using errcode='22023';end if;
 if act in('save','capture') then
  if jsonb_typeof(p_input->'name') is distinct from 'string' or jsonb_typeof(p_input->'notes') is distinct from 'string' then raise exception 'Invalid template text' using errcode='22023';end if;name_text:=btrim(p_input->>'name');note_text:=btrim(p_input->>'notes');if length(name_text) not between 1 and 80 or length(note_text)>1000 then raise exception 'Invalid template text' using errcode='22023';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-task-template-action:'||p_actor::text||':'||aid::text,0));
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into receipt from public.pro_task_template_actions where actor_id=p_actor and action_id=aid;
 if found then if receipt.input is distinct from p_input then raise exception 'Template action identity reused' using errcode='22023';end if;return receipt.result;end if;
 -- Lock every child action BEFORE the target work, matching the original task
 -- writer. No child receipt is adopted without an already committed parent.
 if act='apply' then
  for child_id in select v from unnest(child_ids)v order by v loop perform pg_advisory_xact_lock(hashtextextended('pro-work-task-action:'||p_actor::text||':'||child_id::text,0));end loop;
  perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||work_key,0));
  select * into work from public.pro_work where user_id=p_actor and id=work_key for share;if not found then raise exception 'Forbidden' using errcode='42501';end if;
 elsif act='capture' then
  -- Validate references before deriving the sorted work-lock set.
  for ref in select value from jsonb_array_elements(p_input->'selected') loop
   select array_agg(key order by key) into keys from jsonb_object_keys(ref)key;
   if keys is distinct from array['revision','taskId','workId'] or jsonb_typeof(ref->'workId') is distinct from 'string' or length(ref->>'workId') not between 1 and 160 or jsonb_typeof(ref->'taskId') is distinct from 'string' or jsonb_typeof(ref->'revision') is distinct from 'number' or not coalesce((ref->>'revision')~'^[0-9]{1,10}$',false) or(ref->>'revision')::numeric not between 1 and 2147483647 then raise exception 'Invalid capture reference' using errcode='22023';end if;
   row_id:=(ref->>'taskId')::uuid;if row_id=any(seen) then raise exception 'Repeated capture task' using errcode='22023';end if;seen:=array_append(seen,row_id);
  end loop;
  for source_work in select distinct value->>'workId' from jsonb_array_elements(p_input->'selected') order by 1 loop
   perform pg_advisory_xact_lock(hashtextextended('pro-work-tasks:'||p_actor::text||':'||source_work,0));
  end loop;
  for source_work in select distinct value->>'workId' from jsonb_array_elements(p_input->'selected') order by 1 loop
   perform 1 from public.pro_work where user_id=p_actor and id=source_work for share;if not found then raise exception 'Forbidden' using errcode='42501';end if;
  end loop;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-task-template-definition:'||p_actor::text||':'||template_key::text,0));
 select * into t from public.pro_task_templates where owner_id=p_actor and id=template_key for update;
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if act='apply' then
  if not found then raise exception 'Forbidden' using errcode='42501';end if;
  if t.revision<>rev or t.archived then raise exception 'Template changed' using errcode='40001';end if;
  preview:=public.pro_task_template_preview(p_actor,template_key,work_key,p_input->>'startDate');
  before_json:=jsonb_build_object('template',public.pro_task_template_detail(t),'existingCount',preview->'existingCount');
  if jsonb_array_length(preview->'rows')<>cardinality(new_ids) then raise exception 'Template task count changed' using errcode='40001';end if;
  if exists(select 1 from public.pro_work_task_actions where actor_id=p_actor and action_id=any(child_ids)) or exists(select 1 from public.pro_work_tasks where owner_id=p_actor and id=any(new_ids)) then raise exception 'Task identity already used' using errcode='40001';end if;
  position_index:=1;
  for r in select value from jsonb_array_elements(preview->'rows') loop
   child_input:=jsonb_build_object('action','create','workId',work_key,'taskId',new_ids[position_index],'actionId',child_ids[position_index],'revision',0,'title',r->>'title','details',r->>'details','assignee',r->>'assignee','dueDate',r->'dueDate');
   perform public.pro_work_tasks_mutate(p_actor,child_input);position_index:=position_index+1;
  end loop;
  answer:=jsonb_build_object('action','apply','templateId',template_key,'templateRevision',t.revision,'workId',work_key,'taskIds',to_jsonb(new_ids));
 else
  if found then
   if rev=0 or t.revision<>rev then raise exception 'Template changed' using errcode='40001';end if;
   before_json:=public.pro_task_template_detail(t);
   if act='save' and t.archived or act in('archive','restore') and t.archived=(act='archive') then raise exception 'Template status changed' using errcode='40001';end if;
  else
   if rev<>0 or act not in('save','capture') then raise exception 'Template unavailable' using errcode='42501';end if;
  end if;
  if act='capture' then
   rows_json:='[]'::jsonb;
   for ref in select value from jsonb_array_elements(p_input->'selected') loop
    select * into task from public.pro_work_tasks where owner_id=p_actor and work_id=ref->>'workId' and id=(ref->>'taskId')::uuid and not archived for share;
    if not found then raise exception 'Source task unavailable' using errcode='42501';end if;
    if task.revision<>(ref->>'revision')::integer then raise exception 'Source task changed' using errcode='40001';end if;
    offset_days:=null;
    if include_dates and task.due_date is not null then
     select * into work from public.pro_work where user_id=p_actor and id=task.work_id;
     if work.start~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then source_day:=work.start::date;
     elsif length(work.start)<=80 and work.start~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T' and work.start~'(Z|[+-][0-9]{2}:[0-9]{2})$' then source_day:=(work.start::timestamptz at time zone 'America/Costa_Rica')::date;
     else raise exception 'Source job start date is invalid; disable due dates to copy text only' using errcode='22023';end if;
     if source_day not between date'1900-01-01' and date'2100-12-31' then raise exception 'Source job start date outside range' using errcode='22023';end if;
     offset_days:=task.due_date-source_day;if offset_days not between -80000 and 80000 then raise exception 'Source date offset outside range' using errcode='22023';end if;
    end if;
    rows_json:=rows_json||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'title',task.title,'details',case when include_details then task.details else '' end,'assignee',case when include_manual then task.assignee else '' end,'dueOffset',offset_days));
   end loop;
  elsif act='save' then rows_json:=p_input->'rows';end if;
  if act in('save','capture') then
   if t.id is null then insert into public.pro_task_templates(owner_id,id,name,notes) values(p_actor,template_key,name_text,note_text) returning * into t;
   else update public.pro_task_templates set name=name_text,notes=note_text,revision=revision+1 where owner_id=p_actor and id=template_key returning * into t;end if;
   delete from public.pro_task_template_rows where owner_id=p_actor and template_id=template_key;
   position_index:=0;seen:=array[]::uuid[];
   for r in select value from jsonb_array_elements(rows_json) loop
    select array_agg(key order by key) into keys from jsonb_object_keys(r)key;
    if keys is distinct from array['assignee','details','dueOffset','id','title'] or jsonb_typeof(r->'id') is distinct from 'string' or jsonb_typeof(r->'title') is distinct from 'string' or jsonb_typeof(r->'details') is distinct from 'string' or jsonb_typeof(r->'assignee') is distinct from 'string' or jsonb_typeof(r->'dueOffset') not in('null','number') then raise exception 'Invalid template row' using errcode='22023';end if;
    row_id:=(r->>'id')::uuid;if row_id=any(seen) then raise exception 'Repeated template row' using errcode='22023';end if;seen:=array_append(seen,row_id);
    if r->>'dueOffset' is not null and not coalesce((r->>'dueOffset')~'^-?[0-9]{1,5}$',false) then raise exception 'Invalid relative due date' using errcode='22023';end if;
    insert into public.pro_task_template_rows(owner_id,template_id,id,position,title,details,assignee,due_offset) values(p_actor,template_key,row_id,position_index,btrim(r->>'title'),btrim(r->>'details'),btrim(r->>'assignee'),(r->>'dueOffset')::integer);position_index:=position_index+1;
   end loop;
  else update public.pro_task_templates set archived=act='archive',revision=revision+1 where owner_id=p_actor and id=template_key returning * into t;end if;
  answer:=jsonb_build_object('action',act,'template',public.pro_task_template_summary(t));
 end if;
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 insert into public.pro_task_template_actions(actor_id,action_id,template_id,input,result,before_state,after_state) values(p_actor,aid,template_key,p_input,answer,before_json,case when act='apply' then null else public.pro_task_template_detail(t) end);return answer;
end $$;
create or replace function public.pro_task_template_action_read(p_actor uuid,p_action uuid) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare r public.pro_task_template_actions;
begin
 if not coalesce(public.pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_task_template_actions where actor_id=p_actor and action_id=p_action;if not found then return jsonb_build_object('receipt',null);end if;
 return jsonb_build_object('receipt',jsonb_build_object('input',r.input,'result',r.result));
end $$;
drop trigger if exists pro_task_template_actions_immutable on public.pro_task_template_actions;
create trigger pro_task_template_actions_immutable before update on public.pro_task_template_actions for each row execute function public.pro_team_append_only();
alter table public.pro_task_templates enable row level security;alter table public.pro_task_template_rows enable row level security;alter table public.pro_task_template_actions enable row level security;
revoke all on public.pro_task_templates,public.pro_task_template_rows,public.pro_task_template_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_task_templates,public.pro_task_template_rows,public.pro_task_template_actions to service_role;
revoke all on function public.pro_task_template_summary(public.pro_task_templates),public.pro_task_template_detail(public.pro_task_templates),public.pro_task_templates_read(uuid,text,text,uuid,uuid),public.pro_task_template_preview(uuid,uuid,text,text),public.pro_task_templates_mutate(uuid,jsonb),public.pro_task_template_action_read(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_task_template_summary(public.pro_task_templates),public.pro_task_template_detail(public.pro_task_templates),public.pro_task_templates_read(uuid,text,text,uuid,uuid),public.pro_task_template_preview(uuid,uuid,text,text),public.pro_task_templates_mutate(uuid,jsonb),public.pro_task_template_action_read(uuid,uuid) to service_role;
commit;
